#[derive(Debug, Default)]
pub struct TableData {
    pub rows: Vec<RowEntry>,
    pub pk_index: HashMap<String, usize>,
    vector_index: Mutex<HashMap<String, VectorIndex>>,
    secondary_indexes: Mutex<HashMap<String, SecondaryIndex>>,
    /// Where this table's rows live. `Resident` (the default) keeps the full row set in
    /// `rows`/`pk_index` as today; `Streaming` keeps `rows` empty and reads rows from the
    /// on-disk segment on demand. Reads run under `&self`, so a streaming table can only be
    /// *read* (pure file I/O) while `&self`; any write materializes it back to `Resident`
    /// under `&mut self` first. See `Engine::for_each_table_row`.
    residency: TableResidency,
}

/// Residency of a table's rows: fully in memory, or backed by an on-disk segment that is
/// streamed at read time so the table need not be materialized to be scanned.
#[derive(Debug, Default)]
enum TableResidency {
    #[default]
    Resident,
    Streaming {
        segment: PathBuf,
        /// Offsets + value dictionary for the segment (never the rows). Boxed so the common
        /// `Resident` case keeps `TableData.residency` pointer-small. Built at load.
        index: Box<StreamingIndex>,
    },
}

impl TableData {
    /// True when the table's rows are fully in memory (the default). False for a
    /// segment-backed `Streaming` table, whose `rows` is empty and is read on demand via
    /// the segment. Resident-only fast paths (e.g. slice/cursor batch scans, in-memory index
    /// access) must gate on this and let streaming tables fall through to the read seam.
    fn is_resident(&self) -> bool {
        matches!(self.residency, TableResidency::Resident)
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct TableKey {
    db: String,
    table: String,
}

// -----------------------------
// Engine
// -----------------------------

#[derive(Debug)]
pub struct Engine {
    data_dir: PathBuf,
    storage_mode: TableStorageMode,

    catalog: Catalog,
    tables: HashMap<TableKey, TableData>,

    /// Global change sequence for CDC.
    change_seq: u64,
    changes: Vec<ChangeEvent>,
    cdc_retention_events: usize,

    /// Prepared queries.
    prepared: HashMap<String, PreparedQuery>,
    next_prepared_id: u64,

    /// Simple in-memory query result cache keyed by ETag.
    ///
    /// This is safe because the ETag includes the (conservative) dependency
    /// signature. When dependencies change, ETags change, and old entries are
    /// naturally bypassed.
    cached_select: Mutex<HashMap<String, CachedSelect>>,

    /// Patch cache: computed deltas keyed by (base_etag -> current_etag).
    ///
    /// This allows many clients to share the same computed patch and reduces
    /// repeated diff work under high fan-out reads.
    cached_patch: Mutex<HashMap<PatchCacheKey, PatchDelta>>,

    /// Research: ValueStore with learned index lookup instrumentation.
    value_store: Mutex<ValueStore>,

    /// Research: column snapshot manager for adaptive row/column execution.
    snapshots: Mutex<SnapshotManager>,

    /// Research: index advisor telemetry (R16).
    index_advisor: Mutex<IndexAdvisor>,
    index_advisor_persist: bool,
    index_advisor_history: Vec<AdvisorHistoryEntry>,
    index_advisor_history_next_id: u64,
    index_advisor_metrics: Mutex<AdvisorMetrics>,

    /// Research: query intent inference (R17).
    intent_history: Mutex<Vec<IntentQuerySample>>,

    /// Research: semantic autoparameterization feedback loop (R11).
    autoparam_feedback: Mutex<HashMap<String, AutoparamFeedbackEntry>>,
    autoparam_metrics: Mutex<AutoparamMetrics>,

    /// Research: DP budget manager + audit log.
    dp_budgets: HashMap<String, DpBudget>,
    dp_audit: Vec<DpAuditEvent>,
    dp_audit_next_id: u64,

    /// Research: oblivious execution policies.
    oblivious_policies: HashMap<TableKey, ObliviousPolicy>,

    /// Research: forensic hash chain (prototype).
    forensic_chain: Vec<ForensicRecord>,
    forensic_next_id: u64,
    /// Research: checkpoint anchors for audit verification (T091).
    checkpoint_anchors: Vec<CheckpointAnchor>,
    audit_last_verified_ms: u64,

    /// Research: merge policies for optimistic concurrency.
    merge_policies: HashMap<TableKey, MergePolicySpec>,

    /// Research: merge wasm registry (prototype).
    merge_wasm_registry: HashMap<String, MergeWasmModuleEntry>,

    /// Research: materialized views for incremental maintenance.
    views: HashMap<TableKey, ViewState>,

    /// Research: edge bundle coverage tracking (R14).
    edge_coverage: HashMap<TableKey, Vec<EdgeCoverage>>,

    /// Research: HNSW vector indexes for approximate nearest neighbor (R10). Behind a `RwLock`
    /// (interior mutability) so the write path can invalidate/rebuild indexes through `&self` —
    /// a step toward per-database write-lock sharding (search reads share the lock).
    hnsw_indexes: RwLock<HashMap<HnswIndexKey, HnswIndex>>,

    /// Research: schema evolution tracking (R15).
    schema_versions: HashMap<TableKey, u64>,
    schema_changes: Vec<SchemaChangeEntry>,
    schema_changes_next_id: u64,
    schema_flags: HashMap<TableKey, TableSchemaFlags>,

    /// API tokens for security (T122).
    api_tokens: HashMap<String, ApiToken>,
    api_token_next_id: u64,

    /// Database users (T044).
    db_users: HashMap<String, DbUser>,

    /// In-memory database key manager (T190 / T191 / T192 / T193).
    ///
    /// Master key material is intentionally **not persisted** here — operators must
    /// re-register keys after restart via `settings.encryption.register_key`. Mode and
    /// active-key metadata is persisted under `data/encryption.json` (without the keys
    /// themselves) so the engine knows what to expect after restart.
    key_manager: skeindb_core::encryption::DatabaseKeyManager,
    encryption_audit: Vec<EncryptionAuditEntry>,
    encryption_audit_next_id: u64,

    /// Tables whose on-disk rows contain encrypted-at-rest cells (T193) that could not be
    /// decrypted at load time because the database master key is not currently registered.
    /// Such tables are loaded as empty in memory and are blocked from being persisted (which
    /// would otherwise overwrite the ciphertext with empty/plaintext data). They are
    /// transparently reloaded once the matching key is registered.
    encrypted_locked_tables: HashSet<TableKey>,

    /// Tables whose primary on-disk file is present but unreadable (corrupt/truncated).
    /// Loaded empty and blocked from being persisted so the corrupt bytes are preserved
    /// for recovery rather than silently overwritten with an empty table.
    corrupt_tables: HashSet<TableKey>,

    /// Per-database write-ahead log writers for row-level redo (crash recovery of table
    /// data). Each database logs to its own WAL under `<data_dir>/wal/<db>/`, opened lazily
    /// on that database's first mutation and truncated at each checkpoint. Partitioning the
    /// WAL per database keeps one database's append+fsync independent of another's — the
    /// durability-side prerequisite for per-database write-lock sharding. See `engine/wal.rs`.
    /// Behind a `Mutex` (interior mutability) so the write path can log through `&self` — a
    /// step toward per-database write-lock sharding.
    wals: Mutex<HashMap<String, DbWal>>,
    /// Monotonic transaction id stamped on WAL records. Shared across databases; each
    /// per-database WAL only ever sees a subset and pairs begin/commit by id within its file.
    /// Atomic so it can be advanced through `&self`.
    wal_next_txn: AtomicU64,
    /// Group-commit batch size: fsync a database's WAL once every this many committed
    /// transactions (read once from `SKEINDB_WAL_SYNC_BATCH` at open; default 1 = fsync every
    /// commit = strongest durability). A larger value amortizes the fsync — fewer
    /// fsync-under-lock stalls, higher write throughput — at the cost of losing at most
    /// `batch-1` most-recent commits per database on a power-loss crash (recovery stays a
    /// consistent prefix either way).
    wal_sync_batch: u64,

    /// Tables mutated since the last snapshot flush. With the WAL providing per-commit
    /// durability, row mutations defer their full-table snapshot rewrite: the table is
    /// marked dirty here and flushed in a batch (see `flush_dirty_tables`), removing the
    /// O(rows) write amplification of persisting on every single mutation.
    dirty_tables: HashSet<TableKey>,
    /// Row mutations since the last flush; when it reaches `WAL_FLUSH_THRESHOLD` the dirty
    /// tables are flushed and the WAL is truncated, bounding WAL size and replay time.
    mutations_since_flush: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EncryptionAuditEntry {
    pub id: u64,
    pub event_ms: u64,
    pub action: String,
    pub db: Option<String>,
    pub key_id: Option<String>,
    pub previous_key_id: Option<String>,
    pub mode: Option<String>,
    pub note: Option<String>,
}

#[derive(Debug, Clone)]
struct CachedSelect {
    columns: Vec<ColumnMeta>,
    rows: Vec<Vec<Lit>>,
    keys: Option<Vec<Vec<Lit>>>,
    // Plan cache metadata (T211)
    query: Option<String>,
    hits: u64,
    created_ms: u64,
    last_hit_ms: u64,
    schema_version: u64,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct PatchCacheKey {
    base: String,
    cur: String,
}

#[derive(Debug, Clone)]
struct PatchDelta {
    columns: Vec<ColumnMeta>,
    window: Option<WindowInfo>,

    added: Vec<PatchRow>,
    updated: Vec<PatchRow>,
    removed: Vec<Vec<Lit>>,

    /// Row movement information for ordered windows.
    moved: Vec<PatchMove>,

    /// Compressed reorder hint (e.g., uniform shift) when applicable.
    reorder: Option<ReorderHint>,

    /// True if this patch is best-effort/partial (optimization-only modes).
    partial: bool,
    /// True if removals are unknown in this response.
    removed_unknown: bool,
    /// True if updates are unknown in this response.
    updated_unknown: bool,

    /// If set, indicates why the server requested a reset (no patch available).
    reset_reason: Option<String>,
}

#[derive(Debug, Clone)]
struct WindowInfo {
    limit: Option<u64>,
    offset: Option<u64>,
}

#[derive(Debug, Clone)]
struct PatchRow {
    pk: Vec<Lit>,
    row: Vec<Lit>,
    /// Position in the *current* window.
    at: usize,
}

#[derive(Debug, Clone)]
struct PatchMove {
    pk: Vec<Lit>,
    from: usize,
    to: usize,
}

#[derive(Debug, Clone)]
struct ReorderHint {
    kind: String,
    delta: i64,
    coverage: f64,
}

