#[derive(Debug, Clone, Serialize, Deserialize)]
struct DpBudget {
    principal: String,
    total_epsilon: f64,
    total_delta: f64,
    consumed_epsilon: f64,
    consumed_delta: f64,
    refresh_window_ms: Option<u64>,
    refreshed_at_ms: u64,
    /// Rényi DP composition tracker: accumulated RDP cost at multiple alpha orders.
    /// Each entry is (alpha, rdp_epsilon). Conversion to (ε,δ)-DP uses:
    ///   ε = rdp_epsilon - ln(δ)/(α-1)
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    rdp_alphas: Vec<(f64, f64)>,
    /// Number of composed queries (for advanced composition theorem).
    #[serde(default)]
    query_count: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DpBudgetDisk {
    format_version: u32,
    budgets: Vec<DpBudget>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DpAuditEvent {
    id: u64,
    ts_ms: u64,
    principal: String,
    table: String,
    query_fingerprint: String,
    epsilon: f64,
    delta: f64,
    mechanism: String,
    groups: u64,
    rows_examined: u64,
    aggregates: Vec<String>,
    seed: Option<u64>,
    budget_remaining_epsilon: f64,
    budget_remaining_delta: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DpAuditDisk {
    format_version: u32,
    next_id: u64,
    events: Vec<DpAuditEvent>,
}

