    pub fn ai_autoparam_classifiers(
        &self,
        _params: AiAutoparamClassifiersParams,
    ) -> AiAutoparamClassifiersResult {
        AiAutoparamClassifiersResult {
            format: "skein.ai.autoparam.classifiers.v1".to_string(),
            default_classifier: "offline_rules_v1".to_string(),
            classifiers: autoparam_classifier_catalog(),
        }
    }

    pub fn ai_autoparam_classify(
        &self,
        params: AiAutoparamClassifyParams,
    ) -> anyhow::Result<AiAutoparamClassifyResult> {
        if params.literals.is_empty() {
            anyhow::bail!("invalid_request: literals is required");
        }
        let classifier = resolve_autoparam_classifier(params.classifier.as_ref())?;
        let started = Instant::now();

        let mut labels = Vec::with_capacity(params.literals.len());
        for (idx, lit) in params.literals.iter().enumerate() {
            labels.push(classify_autoparam_literal(
                self,
                idx as u64,
                lit,
                params.db.as_deref(),
                params.rules.as_ref(),
                classifier,
            ));
        }

        self.record_autoparam_classifier_latency(started.elapsed());

        Ok(AiAutoparamClassifyResult { labels })
    }

    pub fn ai_autoparam_analyze(
        &self,
        params: AiAutoparamAnalyzeParams,
    ) -> anyhow::Result<AiAutoparamAnalyzeResult> {
        let extract = sql_autoparam_extract(&params.sql);
        if extract.literals.is_empty() {
            anyhow::bail!("invalid_request: no literals found");
        }

        let labels = self
            .ai_autoparam_classify(AiAutoparamClassifyParams {
                sql: Some(params.sql.clone()),
                db: params.db.clone(),
                literals: extract.literals.clone(),
                rules: params.rules.clone(),
                classifier: params.classifier.clone(),
            })?
            .labels;

        let fingerprint = fingerprint_json(&serde_json::json!({
            "sql": extract.normalized_sql,
        }));

        Ok(AiAutoparamAnalyzeResult {
            normalized_sql: extract.normalized_sql,
            fingerprint,
            literals: extract.literals,
            labels,
        })
    }

    pub fn ai_autoparam_feedback(
        &self,
        params: AiAutoparamFeedbackParams,
    ) -> anyhow::Result<AiAutoparamFeedbackResult> {
        let classifier = resolve_autoparam_classifier(params.classifier.as_ref())?.to_string();
        let cache_event = params
            .cache_event
            .as_deref()
            .map(str::trim)
            .filter(|event| !event.is_empty())
            .unwrap_or("plan_cache_miss")
            .to_string();
        let miss_increment = if cache_event == "plan_cache_miss" {
            params.miss_count.unwrap_or(1).max(1)
        } else {
            0
        };

        let analysis = self.ai_autoparam_analyze(AiAutoparamAnalyzeParams {
            sql: params.sql,
            db: params.db,
            rules: params.rules,
            classifier: params.classifier,
        })?;

        let mut feedback = self
            .autoparam_feedback
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let cached_before = feedback.contains_key(&analysis.fingerprint);
        let reclassified = cache_event == "plan_cache_miss" || !cached_before;
        let entry = feedback
            .entry(analysis.fingerprint.clone())
            .or_insert_with(|| AutoparamFeedbackEntry {
                normalized_sql: analysis.normalized_sql.clone(),
                classifier: classifier.clone(),
                cache_event: cache_event.clone(),
                cache_miss_count: 0,
                reclassification_count: 0,
                literals: analysis.literals.clone(),
                labels: analysis.labels.clone(),
            });

        entry.cache_event = cache_event.clone();
        entry.cache_miss_count = entry.cache_miss_count.saturating_add(miss_increment);
        if reclassified {
            entry.reclassification_count = entry.reclassification_count.saturating_add(1);
            entry.normalized_sql = analysis.normalized_sql.clone();
            entry.classifier = classifier.clone();
            entry.literals = analysis.literals.clone();
            entry.labels = analysis.labels.clone();
        }

        Ok(AiAutoparamFeedbackResult {
            format: "skein.ai.autoparam.feedback.v1".to_string(),
            fingerprint: analysis.fingerprint,
            normalized_sql: entry.normalized_sql.clone(),
            cache_event,
            classifier,
            cached_before,
            reclassified,
            cache_miss_count: entry.cache_miss_count,
            reclassification_count: entry.reclassification_count,
            literals: entry.literals.clone(),
            labels: entry.labels.clone(),
        })
    }

    pub fn ai_autoparam_metrics(
        &self,
        _params: AiAutoparamMetricsParams,
        plan_cache_hits: u64,
        plan_cache_misses: u64,
    ) -> AiAutoparamMetricsResult {
        let metrics = self
            .autoparam_metrics
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone();
        let feedback = self
            .autoparam_feedback
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let feedback_cache_miss_count = feedback
            .values()
            .map(|entry| entry.cache_miss_count)
            .sum::<u64>();
        let feedback_reclassifications = feedback
            .values()
            .map(|entry| entry.reclassification_count)
            .sum::<u64>();
        let plan_cache_total = plan_cache_hits.saturating_add(plan_cache_misses);
        let plan_cache_hit_rate = if plan_cache_total == 0 {
            0.0
        } else {
            plan_cache_hits as f64 / plan_cache_total as f64
        };
        let classifier_mean_ns = if metrics.classifier_invocations == 0 {
            0.0
        } else {
            metrics.classifier_total_ns as f64 / metrics.classifier_invocations as f64
        };

        AiAutoparamMetricsResult {
            format: "skein.ai.autoparam.metrics.v1".to_string(),
            plan_cache_hits,
            plan_cache_misses,
            plan_cache_hit_rate,
            classifier_invocations: metrics.classifier_invocations,
            classifier_total_ns: metrics.classifier_total_ns,
            classifier_mean_ns,
            feedback_cache_entries: feedback.len() as u64,
            feedback_cache_miss_count,
            feedback_reclassifications,
        }
    }

    fn record_autoparam_classifier_latency(&self, elapsed: Duration) {
        let elapsed_ns = elapsed.as_nanos().min(u64::MAX as u128) as u64;
        let mut metrics = self
            .autoparam_metrics
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        metrics.classifier_invocations = metrics.classifier_invocations.saturating_add(1);
        metrics.classifier_total_ns = metrics.classifier_total_ns.saturating_add(elapsed_ns);
    }

    pub fn ai_nl_translate(
        &self,
        params: AiNlTranslateParams,
    ) -> anyhow::Result<AiNlTranslateResult> {
        let request = params.request.trim();
        if request.is_empty() {
            anyhow::bail!("invalid_request: request is required");
        }

        let read_only = params.read_only.unwrap_or(true);
        let include_schema = params.include_schema.unwrap_or(true);
        let max_tables = params.max_tables.unwrap_or(16).max(1) as usize;

        let (tables, mut warnings) = if include_schema {
            self.ai_nl_prompt_tables(&params.db, params.tables.as_ref(), max_tables)?
        } else {
            let (_, warnings) = self.ai_nl_prompt_tables(&params.db, params.tables.as_ref(), 0)?;
            (Vec::new(), warnings)
        };

        let prompt = build_nl_prompt(&params.db, request, &tables, read_only);
        let fingerprint = fingerprint_json(&serde_json::json!({
            "db": params.db.as_str(),
            "request": request,
            "tables": tables.iter().map(|t| t.table.clone()).collect::<Vec<_>>(),
            "read_only": read_only
        }));

        if !include_schema {
            warnings.push("schema omitted from prompt".to_string());
        }

        let package = AiNlPromptPackage {
            version: "nl_prompt_v1".to_string(),
            db: params.db.clone(),
            request: request.to_string(),
            read_only,
            tables: tables.clone(),
            prompt,
            fingerprint,
        };

        let query = ai_nl_rule_translate(self, &params.db, request, &tables);

        Ok(AiNlTranslateResult {
            package,
            query,
            warnings,
        })
    }

    pub fn ai_nl_explain(&self, params: AiNlExplainParams) -> anyhow::Result<AiNlExplainResult> {
        let args = params.args.unwrap_or_default();
        let QueryBody::Select { select } = params.query.body.as_ref() else {
            anyhow::bail!("invalid_request: only SELECT queries are supported");
        };

        let mut tables = Vec::new();
        collect_tables(&params.query, &mut tables);
        let mut table_names: Vec<String> = tables
            .into_iter()
            .map(|(db, table)| format!("{db}.{table}"))
            .collect();
        table_names.sort();
        table_names.dedup();

        let projection: Vec<String> = select
            .projection
            .iter()
            .map(|item| infer_select_name(&item.expr))
            .collect();

        let mut filters = Vec::new();
        if let Some(pred) = select.r#where.as_ref() {
            filters.push(render_expr_summary(pred));
        }

        let mut order_by = Vec::new();
        for ob in params.query.order_by.iter() {
            let dir = ob.dir.clone().unwrap_or(OrderDir::Asc);
            let expr = render_expr_summary(&ob.expr);
            order_by.push(format!(
                "{} {}",
                expr,
                match dir {
                    OrderDir::Asc => "asc",
                    OrderDir::Desc => "desc",
                }
            ));
        }

        let limit = params.query.limit.as_ref().and_then(|lim| lim.limit);

        let mut summary = String::new();
        summary.push_str(&format!(
            "Selects {} from {}",
            projection.join(", "),
            table_names.join(", ")
        ));
        if !filters.is_empty() {
            summary.push_str(&format!(" where {}", filters.join(" and ")));
        }
        if !order_by.is_empty() {
            summary.push_str(&format!(" order by {}", order_by.join(", ")));
        }
        if let Some(limit) = limit {
            summary.push_str(&format!(" limit {}", limit));
        }

        let deps_list = self.dependencies_for_query(&params.query)?;
        let approval_token = ai_nl_approval_token(&params.query, &args, &deps_list);
        let deps = serde_json::json!({
            "tables": deps_list
        });

        let (preview, preview_format) = ai_nl_preview(
            self,
            &params.query,
            &args,
            params.preview_limit,
            params.preview_format,
        )?;

        Ok(AiNlExplainResult {
            summary,
            tables: table_names,
            projection,
            filters,
            order_by,
            limit,
            deps,
            approval_token,
            preview,
            preview_format,
        })
    }

    pub fn ai_nl_execute(&self, params: AiNlExecuteParams) -> anyhow::Result<AiNlExecuteResult> {
        let args = params.args.unwrap_or_default();
        let deps_list = self.dependencies_for_query(&params.query)?;
        let expected = ai_nl_approval_token(&params.query, &args, &deps_list);
        if params.approval_token != expected {
            anyhow::bail!("invalid_request: approval_token mismatch");
        }
        let result_format = params.result_format.unwrap_or(ResultFormat::ObjectsJson);
        let want_etag = params.want_etag.unwrap_or(false);
        let if_none_match = params.if_none_match.as_deref();
        let select = self.query_select(
            &params.query,
            &args,
            result_format,
            want_etag,
            if_none_match,
            params.min_causality.as_ref(),
            None,
            false,
            None,
        )?;

        Ok(AiNlExecuteResult {
            etag: select.etag,
            not_modified: select.not_modified,
            data: select.data,
            deps: select.deps,
            causality: select.causality,
            wire: select.wire,
        })
    }

