    fn forensic_flog_path(&self) -> PathBuf {
        self.data_dir.join("forensic.flog")
    }

    /// Compact the append-only CDC + forensic sidecar logs into their full-snapshot files and
    /// truncate the sidecars. Called at the flush/checkpoint boundary: the snapshots are written
    /// durably (fsync), so the sidecars' records are now durable and can be discarded, bounding
    /// each sidecar's size and the crash-recovery replay to one flush interval. Ordering
    /// (snapshot then truncate) means a crash between the two leaves duplicate records that the
    /// loaders drop by `seq`/`id`.
    fn compact_change_forensic_logs(&self) {
        self.persist_changes_best_effort();
        self.persist_forensic_best_effort();
        let _ = fs::remove_file(self.changes_flog_path());
        let _ = fs::remove_file(self.forensic_flog_path());
    }

    fn cdc_subscriptions_path(&self) -> PathBuf {
        self.data_dir.join("cdc_subscriptions.json")
    }

    fn replay_workspaces_dir(&self) -> PathBuf {
        self.data_dir.join(REPLAY_WORKSPACES_DIR)
    }

    fn replay_workspace_dir(&self, workspace_id: &str) -> PathBuf {
        self.replay_workspaces_dir().join(workspace_id)
    }

    fn replay_workspace_bundle_path(workspace_dir: &Path) -> PathBuf {
        workspace_dir.join("bundle.json")
    }

    fn load_changes_best_effort(&mut self) {
        let path = self.changes_path();
        let events = load_json::<ChangeLogDisk>(&path)
            .filter(|disk| (1..=CHANGE_LOG_FORMAT_VERSION).contains(&disk.format_version))
            .map(|disk| disk.events)
            .or_else(|| load_json::<Vec<ChangeEvent>>(&path))
            .unwrap_or_default();
        self.changes = events;
        // Replay the append-only sidecar (records committed since the last snapshot compaction),
        // keeping only records newer than the snapshot so a crash between snapshot-write and
        // sidecar-truncate never double-counts.
        let tail = read_log_records::<ChangeEvent>(&self.changes_flog_path());
        if !tail.is_empty() {
            let snapshot_max_seq = self.changes.last().map(|e| e.seq).unwrap_or(0);
            for ev in tail {
                if ev.seq > snapshot_max_seq {
                    self.changes.push(ev);
                }
            }
        }
        self.trim_retained_change_log();
        self.change_seq = self.changes.last().map(|e| e.seq).unwrap_or(0);
    }

    fn persist_changes_best_effort(&self) {
        let _ = save_json(
            &self.changes_path(),
            &ChangeLogDisk {
                format_version: CHANGE_LOG_FORMAT_VERSION,
                events: self.changes.clone(),
            },
        );
    }

    fn trim_retained_change_log(&mut self) {
        if self.changes.len() <= self.cdc_retention_events {
            return;
        }
        let drop_count = self.changes.len() - self.cdc_retention_events;
        self.changes.drain(0..drop_count);
    }

    fn current_cdc_earliest_offset(&self) -> u64 {
        self.changes.first().map(|event| event.seq).unwrap_or(0)
    }

    fn change_log_bytes(&self) -> u64 {
        serde_json::to_vec(&ChangeLogDisk {
            format_version: CHANGE_LOG_FORMAT_VERSION,
            events: self.changes.clone(),
        })
        .map(|bytes| bytes.len() as u64)
        .unwrap_or(0)
    }

    pub(crate) fn load_cdc_subscriptions_best_effort(&self) -> Subscriptions {
        let Some(disk) = load_json::<CdcSubscriptionsDisk>(&self.cdc_subscriptions_path())
            .filter(|disk| (1..=CDC_SUBSCRIPTIONS_FORMAT_VERSION).contains(&disk.format_version))
        else {
            return Subscriptions::default();
        };

        let mut subs = HashMap::new();
        let mut next_id = disk.next_id;
        for sub in disk.subs {
            next_id = next_id.max(next_subscription_id(&sub.id));
            let sub = Subscription::from(sub);
            subs.insert(sub.id.clone(), sub);
        }
        Subscriptions { subs, next_id }
    }

    fn persist_cdc_subscriptions(&self, subs: &Subscriptions) -> anyhow::Result<()> {
        let path = self.cdc_subscriptions_path();
        if subs.subs.is_empty() {
            return remove_file_if_exists(&path);
        }

        let mut disk_subs = subs
            .subs
            .values()
            .map(CdcSubscriptionDisk::from)
            .collect::<Vec<_>>();
        disk_subs.sort_by(|left, right| left.id.cmp(&right.id));
        save_json(
            &path,
            &CdcSubscriptionsDisk {
                format_version: CDC_SUBSCRIPTIONS_FORMAT_VERSION,
                next_id: subs.next_id,
                subs: disk_subs,
            },
        )
    }

    fn prepared_path(&self) -> PathBuf {
        self.data_dir.join("prepared.json")
    }

    fn load_prepared_best_effort(&mut self) {
        let path = self.prepared_path();
        let list: Vec<PreparedQuery> = load_json(&path).unwrap_or_default();
        for pq in list {
            self.next_prepared_id = self.next_prepared_id.max(
                u64::from_str_radix(pq.id.trim_start_matches("q_").trim_start_matches('0'), 16)
                    .unwrap_or(self.next_prepared_id)
                    + 1,
            );
            self.prepared.insert(pq.id.clone(), pq);
        }
    }

    fn persist_prepared_best_effort(&self) {
        let list: Vec<PreparedQuery> = self.prepared.values().cloned().collect();
        let _ = save_json(&self.prepared_path(), &list);
    }

    fn snapshots_path(&self) -> PathBuf {
        self.data_dir.join("snapshots.json")
    }

    fn snapshots_dir_path(&self) -> PathBuf {
        self.data_dir.join("snapshots")
    }

    fn load_snapshots_best_effort(&mut self) {
        let path = self.snapshots_path();
        let list: Vec<ColumnSnapshotDisk> = load_json(&path).unwrap_or_default();
        if let Ok(mut manager) = self.snapshots.lock() {
            manager.load_from_disk(self, list);
        }
    }

    fn persist_snapshots_best_effort(&self) {
        let list = if let Ok(manager) = self.snapshots.lock() {
            manager.to_disk()
        } else {
            return;
        };
        let _ = save_json(&self.snapshots_path(), &list);
        self.persist_snapshot_segments_best_effort(&list);
    }

    fn persist_snapshot_segments_best_effort(&self, snapshots: &[ColumnSnapshotDisk]) {
        let root = self.snapshots_dir_path();
        if fs::create_dir_all(&root).is_err() {
            return;
        }

        let mut keep = HashSet::new();
        for snapshot in snapshots.iter() {
            let dir_name = snapshot_dir_name(&snapshot.id);
            keep.insert(dir_name.clone());
            let dir = root.join(&dir_name);
            let _ = self.persist_snapshot_segment_dir(snapshot, &dir);
        }

        let Ok(entries) = fs::read_dir(&root) else {
            return;
        };
        for entry in entries.flatten() {
            let Ok(file_type) = entry.file_type() else {
                continue;
            };
            if !file_type.is_dir() {
                continue;
            }
            let name = entry.file_name().to_string_lossy().to_string();
            if !keep.contains(&name) {
                let _ = fs::remove_dir_all(entry.path());
            }
        }
    }

    fn persist_snapshot_segment_dir(
        &self,
        snapshot: &ColumnSnapshotDisk,
        dir: &Path,
    ) -> anyhow::Result<()> {
        let _ = fs::remove_dir_all(dir);
        fs::create_dir_all(dir)?;

        let mut segments = Vec::new();
        for (idx, (column, is_pk)) in snapshot_storage_columns(snapshot).into_iter().enumerate() {
            let file = format!("col-{:04}.cseg", idx + 1);
            let path = dir.join(&file);
            let values = snapshot_column_values(snapshot, &column, is_pk)?;
            let segment = write_snapshot_cseg(&path, snapshot, &column, is_pk, &file, &values)?;
            segments.push(segment);
        }

        let manifest = ColumnSnapshotManifestDisk {
            format_version: SNAPSHOT_MANIFEST_FORMAT_VERSION,
            id: snapshot.id.clone(),
            db: snapshot.db.clone(),
            table: snapshot.table.clone(),
            columns: snapshot.columns.clone(),
            pk_columns: snapshot.pk_columns.clone(),
            snapshot_ts: snapshot.snapshot_ts,
            table_version: snapshot.table_version,
            row_count: snapshot.rows.len() as u64,
            segments,
        };
        save_json(&dir.join("manifest.json"), &manifest)
    }

    fn snapshot_dir_for_id(&self, snapshot_id: &str) -> PathBuf {
        self.snapshots_dir_path()
            .join(snapshot_dir_name(snapshot_id))
    }

    fn load_snapshot_column_scan(
        &self,
        selection: &SnapshotSelection,
        required: &HashSet<String>,
        include_pk: bool,
    ) -> anyhow::Result<SnapshotColumnScan> {
        let dir = self.snapshot_dir_for_id(&selection.id);
        let manifest: ColumnSnapshotManifestDisk = load_json(&dir.join("manifest.json"))
            .ok_or_else(|| anyhow::anyhow!("missing snapshot manifest for {}", selection.id))?;
        if manifest.format_version != SNAPSHOT_MANIFEST_FORMAT_VERSION {
            anyhow::bail!(
                "unsupported snapshot manifest version: {}",
                manifest.format_version
            );
        }
        if manifest.id != selection.id
            || manifest.db != selection.db
            || manifest.table != selection.table
        {
            anyhow::bail!("snapshot manifest mismatch for {}", selection.id);
        }
        if manifest.table_version != selection.table_version {
            anyhow::bail!(
                "snapshot manifest table version mismatch for {}",
                selection.id
            );
        }
        if manifest.snapshot_ts != selection.snapshot_ts {
            anyhow::bail!("snapshot manifest timestamp mismatch for {}", selection.id);
        }

        let mut loaded_columns = Vec::new();
        let mut column_values = HashMap::new();

        for column in selection.pk_columns.iter() {
            if !(include_pk || required.contains(column)) || column_values.contains_key(column) {
                continue;
            }
            let values =
                self.load_snapshot_segment_values(&dir, &manifest, selection, column, true)?;
            loaded_columns.push(column.clone());
            column_values.insert(column.clone(), values);
        }

        for column in selection.columns.iter() {
            if !required.contains(column) || column_values.contains_key(column) {
                continue;
            }
            let values =
                self.load_snapshot_segment_values(&dir, &manifest, selection, column, false)?;
            loaded_columns.push(column.clone());
            column_values.insert(column.clone(), values);
        }

        let row_count = if let Some(values) = column_values.values().next() {
            values.len()
        } else {
            manifest.row_count as usize
        };
        if row_count as u64 != manifest.row_count {
            anyhow::bail!("snapshot manifest row count mismatch for {}", selection.id);
        }
        for values in column_values.values() {
            if values.len() != row_count {
                anyhow::bail!("snapshot column length mismatch for {}", selection.id);
            }
        }

        Ok(SnapshotColumnScan {
            loaded_columns,
            pk_columns: selection.pk_columns.clone(),
            column_values,
            row_count,
        })
    }

    fn load_snapshot_segment_values(
        &self,
        dir: &Path,
        manifest: &ColumnSnapshotManifestDisk,
        selection: &SnapshotSelection,
        column: &str,
        is_pk: bool,
    ) -> anyhow::Result<Vec<Lit>> {
        let segment = snapshot_manifest_segment(manifest, column, is_pk)?;
        let decoded = read_snapshot_cseg(&dir.join(&segment.file))?;
        if decoded.db != selection.db || decoded.table != selection.table {
            anyhow::bail!("snapshot cseg table mismatch for {}", selection.id);
        }
        if decoded.column != column || decoded.is_pk != is_pk {
            anyhow::bail!("snapshot cseg column mismatch for {}", selection.id);
        }
        if decoded.snapshot_ts != selection.snapshot_ts {
            anyhow::bail!("snapshot cseg timestamp mismatch for {}", selection.id);
        }
        if decoded.values.len() as u64 != segment.row_count {
            anyhow::bail!("snapshot cseg row count mismatch for {}", selection.id);
        }
        Ok(decoded.values)
    }

    fn advisor_patterns_path(&self) -> PathBuf {
        self.data_dir.join("advisor_patterns.json")
    }

    fn advisor_history_path(&self) -> PathBuf {
        self.data_dir.join("advisor_history.json")
    }

    fn load_advisor_best_effort(&mut self) {
        if !self.index_advisor_persist {
            return;
        }
        if let Some(disk) = load_json::<AdvisorPatternsDisk>(&self.advisor_patterns_path()) {
            if disk.format_version == ADVISOR_PATTERNS_FORMAT_VERSION {
                if let Ok(mut advisor) = self.index_advisor.lock() {
                    advisor.load_from_disk(disk.patterns);
                }
            }
        }
        if let Some(disk) = load_json::<AdvisorHistoryDisk>(&self.advisor_history_path()) {
            if matches!(disk.format_version, 1 | ADVISOR_HISTORY_FORMAT_VERSION) {
                self.index_advisor_history = disk.entries;
                self.index_advisor_history_next_id = disk.next_id.max(1);
            }
        }
    }

    fn restore_advisor_indexes(&mut self) {
        if self.index_advisor_history.is_empty() {
            return;
        }
        let mut latest: HashMap<String, &AdvisorHistoryEntry> = HashMap::new();
        for entry in self.index_advisor_history.iter() {
            latest.insert(entry.suggestion_id.clone(), entry);
        }

        for entry in latest.values() {
            if entry.action != "apply" {
                continue;
            }
            if !matches!(entry.status.as_deref(), None | Some("completed" | "exists")) {
                continue;
            }
            if entry.columns.is_empty() {
                continue;
            }
            let columns = dedup_in_order(&entry.columns);
            let mut include = dedup_in_order(&entry.include);
            include.retain(|col| !columns.contains(col));
            let table = BaseTableRef {
                db: entry.table.db.clone(),
                table: entry.table.table.clone(),
                r#as: None,
            };
            let Ok((schema, tdata)) = self.get_table(&table) else {
                continue;
            };
            if validate_columns(schema, &columns).is_err() {
                continue;
            }
            if validate_columns(schema, &include).is_err() {
                continue;
            }
            let _ = register_secondary_index(schema, tdata, &columns, &include);
        }
    }

    fn persist_advisor_patterns_best_effort(&self) {
        if !self.index_advisor_persist {
            return;
        }
        if let Ok(advisor) = self.index_advisor.lock() {
            let disk = advisor.to_disk();
            let _ = save_json(&self.advisor_patterns_path(), &disk);
        }
    }

    fn persist_advisor_history_best_effort(&self) {
        if !self.index_advisor_persist {
            return;
        }
        let disk = AdvisorHistoryDisk {
            format_version: ADVISOR_HISTORY_FORMAT_VERSION,
            next_id: self.index_advisor_history_next_id,
            entries: self.index_advisor_history.clone(),
        };
        let _ = save_json(&self.advisor_history_path(), &disk);
    }

