    fn views_path(&self) -> PathBuf {
        self.data_dir.join("views.json")
    }

    fn load_views_best_effort(&mut self) {
        if let Some(disk) = load_json::<ViewDisk>(&self.views_path()) {
            if matches!(disk.format_version, 1 | VIEW_FORMAT_VERSION) {
                let mut map = HashMap::new();
                for entry in disk.views.into_iter() {
                    let mut rows = Vec::new();
                    let mut pk_index = HashMap::new();
                    for (idx, row) in entry.rows.into_iter().enumerate() {
                        let key = pk_key(&row.pk);
                        pk_index.insert(key, idx);
                        rows.push(ViewRow {
                            pk: row.pk,
                            values: row.values,
                        });
                    }
                    let mut deps = entry.deps;
                    normalize_view_dependencies(&entry.query, &mut deps);
                    let mut source_rows = HashMap::new();
                    for row in entry.source_rows.into_iter() {
                        source_rows.insert(
                            pk_key(&row.pk),
                            ViewSourceRow {
                                pk: row.pk,
                                row: row.row,
                            },
                        );
                    }
                    map.insert(
                        TableKey {
                            db: entry.db.clone(),
                            table: entry.name.clone(),
                        },
                        ViewState {
                            db: entry.db,
                            name: entry.name,
                            query: entry.query,
                            columns: entry.columns,
                            pk_columns: entry.pk_columns,
                            deps,
                            rows,
                            source_rows,
                            pk_index,
                            last_refresh_ms: entry.last_refresh_ms,
                            last_change_seq: entry.last_change_seq,
                            stale: entry.stale,
                            last_refresh_mode: if entry.last_refresh_mode.is_empty() {
                                "full".to_string()
                            } else {
                                entry.last_refresh_mode
                            },
                        },
                    );
                }
                self.views = map;
            }
        }
    }

    fn persist_views_best_effort(&self) {
        let mut views = self
            .views
            .values()
            .map(|view| {
                let mut source_rows = view
                    .source_rows
                    .values()
                    .map(|row| ViewSourceRowDisk {
                        pk: row.pk.clone(),
                        row: row.row.clone(),
                    })
                    .collect::<Vec<_>>();
                source_rows.sort_by_key(|a| pk_key(&a.pk));
                ViewEntryDisk {
                    db: view.db.clone(),
                    name: view.name.clone(),
                    query: view.query.clone(),
                    columns: view.columns.clone(),
                    pk_columns: view.pk_columns.clone(),
                    deps: view.deps.clone(),
                    rows: view
                        .rows
                        .iter()
                        .map(|row| ViewRowDisk {
                            pk: row.pk.clone(),
                            values: row.values.clone(),
                        })
                        .collect(),
                    source_rows,
                    last_refresh_ms: view.last_refresh_ms,
                    last_change_seq: view.last_change_seq,
                    stale: view.stale,
                    last_refresh_mode: view.last_refresh_mode.clone(),
                }
            })
            .collect::<Vec<_>>();
        views.sort_by_key(|a| (a.db.clone(), a.name.clone()));
        let _ = save_json(
            &self.views_path(),
            &ViewDisk {
                format_version: VIEW_FORMAT_VERSION,
                views,
            },
        );
    }

    fn schema_versions_path(&self) -> PathBuf {
        self.data_dir.join("schema_versions.json")
    }

    fn schema_changes_path(&self) -> PathBuf {
        self.data_dir.join("schema_changes.json")
    }

    fn schema_flags_path(&self) -> PathBuf {
        self.data_dir.join("schema_flags.json")
    }

    fn encryption_state_path(&self) -> PathBuf {
        self.data_dir.join("encryption.json")
    }

    fn load_schema_versions_best_effort(&mut self) {
        let mut versions = HashMap::new();
        if let Some(disk) = load_json::<SchemaVersionsDisk>(&self.schema_versions_path()) {
            if disk.format_version == SCHEMA_VERSION_FORMAT_VERSION {
                for entry in disk.versions {
                    versions.insert(
                        TableKey {
                            db: entry.db,
                            table: entry.table,
                        },
                        entry.version.max(1),
                    );
                }
            }
        }

        let mut touched = false;
        for (db, d) in self.catalog.databases.iter() {
            for table in d.tables.keys() {
                let key = TableKey {
                    db: db.clone(),
                    table: table.clone(),
                };
                if let std::collections::hash_map::Entry::Vacant(e) = versions.entry(key) {
                    e.insert(1);
                    touched = true;
                }
            }
        }

        self.schema_versions = versions;
        if touched {
            self.persist_schema_versions_best_effort();
        }
    }

    fn normalize_loaded_row_schema_versions_best_effort(&mut self) {
        let schema_versions = self.schema_versions.clone();
        for (key, tdata) in self.tables.iter_mut() {
            let schema_version = schema_versions.get(key).copied().unwrap_or(1).max(1);
            stamp_rows_schema_version_if_missing(&mut tdata.rows, schema_version);
        }
    }

    fn persist_schema_versions_best_effort(&self) {
        let mut versions = self
            .schema_versions
            .iter()
            .map(|(key, version)| SchemaVersionEntry {
                db: key.db.clone(),
                table: key.table.clone(),
                version: *version,
            })
            .collect::<Vec<_>>();
        versions.sort_by_key(|a| (a.db.clone(), a.table.clone()));
        let _ = save_json(
            &self.schema_versions_path(),
            &SchemaVersionsDisk {
                format_version: SCHEMA_VERSION_FORMAT_VERSION,
                versions,
            },
        );
    }

    fn load_schema_changes_best_effort(&mut self) {
        if let Some(disk) = load_json::<SchemaChangesDisk>(&self.schema_changes_path()) {
            if disk.format_version == 1 || disk.format_version == SCHEMA_CHANGES_FORMAT_VERSION {
                self.schema_changes = disk.changes;
                self.schema_changes_next_id = disk.next_id.max(1);
                if disk.format_version != SCHEMA_CHANGES_FORMAT_VERSION {
                    self.persist_schema_changes_best_effort();
                }
                return;
            }
        }
        self.schema_changes = Vec::new();
        self.schema_changes_next_id = 1;
    }

    fn persist_schema_changes_best_effort(&self) {
        let _ = save_json(
            &self.schema_changes_path(),
            &SchemaChangesDisk {
                format_version: SCHEMA_CHANGES_FORMAT_VERSION,
                next_id: self.schema_changes_next_id,
                changes: self.schema_changes.clone(),
            },
        );
    }

    fn load_schema_flags_best_effort(&mut self) {
        let mut flags = HashMap::new();
        if let Some(disk) = load_json::<SchemaFlagsDisk>(&self.schema_flags_path()) {
            if disk.format_version == SCHEMA_FLAGS_FORMAT_VERSION {
                for entry in disk.tables {
                    let key = TableKey {
                        db: entry.db,
                        table: entry.table,
                    };
                    let interned_columns = entry
                        .interned_columns
                        .into_iter()
                        .filter(|name| !name.trim().is_empty())
                        .collect::<HashSet<_>>();
                    if !interned_columns.is_empty() {
                        flags.insert(key, TableSchemaFlags { interned_columns });
                    }
                }
            }
        }

        let mut normalized = HashMap::new();
        let mut touched = false;
        for (key, table_flags) in flags.into_iter() {
            let Some(schema) = self
                .catalog
                .databases
                .get(&key.db)
                .and_then(|database| database.tables.get(&key.table))
            else {
                touched = true;
                continue;
            };

            let mut interned_columns = HashSet::new();
            for column in table_flags.interned_columns.into_iter() {
                let Some(canonical) = canonical_schema_column_name(schema, &column) else {
                    touched = true;
                    continue;
                };
                if !interned_columns.insert(canonical.to_string()) {
                    touched = true;
                }
            }

            if interned_columns.is_empty() {
                touched = true;
                continue;
            }
            normalized.insert(key, TableSchemaFlags { interned_columns });
        }

        self.schema_flags = normalized;
        if touched {
            self.persist_schema_flags_best_effort();
        }
    }

    fn persist_schema_flags_best_effort(&self) {
        let mut tables = self
            .schema_flags
            .iter()
            .filter_map(|(key, flags)| {
                if flags.interned_columns.is_empty() {
                    return None;
                }
                let mut interned_columns =
                    flags.interned_columns.iter().cloned().collect::<Vec<_>>();
                interned_columns.sort();
                Some(TableSchemaFlagsEntry {
                    db: key.db.clone(),
                    table: key.table.clone(),
                    interned_columns,
                })
            })
            .collect::<Vec<_>>();
        tables.sort_by_key(|a| (a.db.clone(), a.table.clone()));
        let _ = save_json(
            &self.schema_flags_path(),
            &SchemaFlagsDisk {
                format_version: SCHEMA_FLAGS_FORMAT_VERSION,
                tables,
            },
        );
    }

    fn load_encryption_state_best_effort(&mut self) {
        let Some(disk) = load_json::<EncryptionStateDisk>(&self.encryption_state_path()) else {
            self.key_manager.load_profiles(Vec::new());
            self.encryption_audit.clear();
            self.encryption_audit_next_id = 1;
            return;
        };
        if disk.format_version != ENCRYPTION_STATE_FORMAT_VERSION {
            self.key_manager.load_profiles(Vec::new());
            self.encryption_audit.clear();
            self.encryption_audit_next_id = 1;
            return;
        }

        self.key_manager.load_profiles(disk.databases);
        self.encryption_audit = disk.audit;
        self.encryption_audit_next_id = disk.next_audit_id.max(1);
    }

    fn persist_encryption_state_best_effort(&self) {
        let _ = save_json(
            &self.encryption_state_path(),
            &EncryptionStateDisk {
                format_version: ENCRYPTION_STATE_FORMAT_VERSION,
                databases: self.key_manager.profiles(),
                audit: self.encryption_audit.clone(),
                next_audit_id: self.encryption_audit_next_id,
            },
        );
    }

    fn column_is_interned(&self, key: &TableKey, column: &str) -> bool {
        self.schema_flags
            .get(key)
            .map(|flags| flags.interned_columns.contains(column))
            .unwrap_or(false)
    }

    #[cfg_attr(not(test), allow(dead_code))]
    fn set_column_interned_flag(&mut self, key: &TableKey, column: &str, interned: bool) -> bool {
        if interned {
            let flags = self.schema_flags.entry(key.clone()).or_default();
            flags.interned_columns.insert(column.to_string())
        } else if let Some(flags) = self.schema_flags.get_mut(key) {
            let removed = flags.interned_columns.remove(column);
            if flags.interned_columns.is_empty() {
                self.schema_flags.remove(key);
            }
            removed
        } else {
            false
        }
    }

    fn rename_schema_flag_column(&mut self, key: &TableKey, old_name: &str, new_name: &str) {
        let Some(flags) = self.schema_flags.get_mut(key) else {
            return;
        };
        if !flags.interned_columns.remove(old_name) {
            return;
        }
        flags.interned_columns.insert(new_name.to_string());
    }

    fn remove_schema_flag_column(&mut self, key: &TableKey, column_name: &str) {
        let Some(flags) = self.schema_flags.get_mut(key) else {
            return;
        };
        flags.interned_columns.remove(column_name);
        if flags.interned_columns.is_empty() {
            self.schema_flags.remove(key);
        }
    }

    fn emit_change(
        &mut self,
        db: &str,
        table: &str,
        op: &str,
        pk: Option<Vec<Lit>>,
        before: Option<RowObject>,
        after: Option<RowObject>,
    ) {
        self.change_seq += 1;
        let pk_for_forensic = pk.clone();
        self.changes.push(ChangeEvent {
            seq: self.change_seq,
            db: db.to_string(),
            table: table.to_string(),
            op: op.to_string(),
            pk,
            before,
            after,
            query_id: None,
            etag: None,
            commit_ts_ms: now_millis(),
            lsn: Some(self.change_seq),
        });
        let changes_flog = self.changes_flog_path();
        if let Some(ev) = self.changes.last() {
            append_log_record(&changes_flog, ev);
        }
        self.trim_retained_change_log();
        self.append_forensic_record(db, table, op, self.change_seq, pk_for_forensic);
        self.mark_views_stale(db, table);
    }

    fn last_change_seq_for_table(&self, key: &TableKey) -> u64 {
        self.changes
            .iter()
            .rev()
            .find(|ev| ev.db == key.db && ev.table == key.table)
            .map(|ev| ev.seq)
            .unwrap_or(0)
    }

    fn first_change_seq_for_table(&self, key: &TableKey) -> Option<u64> {
        self.changes
            .iter()
            .filter(|ev| ev.db == key.db && ev.table == key.table)
            .map(|ev| ev.seq)
            .min()
    }

    fn edge_coverage_list(&self) -> Vec<EdgeBundleCoverage> {
        let mut out = Vec::new();
        for covers in self.edge_coverage.values() {
            for cover in covers.iter() {
                out.push(EdgeBundleCoverage {
                    table: BaseTableRef {
                        db: cover.table.db.clone(),
                        table: cover.table.table.clone(),
                        r#as: None,
                    },
                    start_seq: cover.start_seq,
                    end_seq: cover.end_seq,
                    updated_at_ms: cover.updated_at_ms,
                    bundle_id: cover.bundle_id.clone(),
                    redaction_mode: cover.redaction_mode.clone(),
                });
            }
        }
        out.sort_by(|a, b| {
            (
                a.table.db.clone(),
                a.table.table.clone(),
                a.start_seq,
                a.end_seq,
            )
                .cmp(&(
                    b.table.db.clone(),
                    b.table.table.clone(),
                    b.start_seq,
                    b.end_seq,
                ))
        });
        out
    }

    fn merge_edge_coverage_windows(windows: &mut Vec<EdgeCoverage>) {
        windows.sort_by_key(|a| (a.start_seq, a.end_seq));
        let mut merged: Vec<EdgeCoverage> = Vec::with_capacity(windows.len());
        for current in windows.drain(..) {
            if let Some(last) = merged.last_mut() {
                if current.start_seq <= last.end_seq.saturating_add(1) {
                    let take_metadata = current.updated_at_ms >= last.updated_at_ms
                        || current.end_seq >= last.end_seq;
                    last.start_seq = last.start_seq.min(current.start_seq);
                    last.end_seq = last.end_seq.max(current.end_seq);
                    if take_metadata {
                        last.bundle_id = current.bundle_id;
                        last.redaction_mode = current.redaction_mode;
                        last.updated_at_ms = current.updated_at_ms;
                    }
                    continue;
                }
            }
            merged.push(current);
        }
        *windows = merged;
    }

    fn edge_contiguous_coverage_end(windows: &[EdgeCoverage], required_start: u64) -> (u64, bool) {
        let mut merged = windows.to_vec();
        Self::merge_edge_coverage_windows(&mut merged);
        let mut covered_through = if required_start == 0 {
            0
        } else {
            required_start.saturating_sub(1)
        };
        for window in merged.into_iter() {
            if window.end_seq <= covered_through {
                continue;
            }
            if window.start_seq > covered_through.saturating_add(1) {
                return (covered_through, true);
            }
            covered_through = covered_through.max(window.end_seq);
        }
        (covered_through, false)
    }

    fn schema_version_for(&self, key: &TableKey) -> u64 {
        self.schema_versions.get(key).copied().unwrap_or(1)
    }

    fn set_schema_version(&mut self, key: &TableKey, version: u64) {
        self.schema_versions.insert(key.clone(), version.max(1));
    }

    pub fn causality_for_relation(&self, db: &str, table: &str) -> anyhow::Result<CausalityToken> {
        let dep = if let Ok(schema) = self.get_schema(db, table) {
            CausalityDependency {
                table: format!("{db}.{table}"),
                v: Some(schema.table_version),
                view: None,
                change_seq: None,
                stale: None,
            }
        } else if let Some(view) = self.views.get(&TableKey {
            db: db.to_string(),
            table: table.to_string(),
        }) {
            CausalityDependency {
                table: format!("{db}.{table}"),
                v: None,
                view: Some(true),
                change_seq: Some(view.last_change_seq),
                stale: Some(view.stale),
            }
        } else {
            anyhow::bail!("table not found: {db}.{table}");
        };
        Ok(build_causality_token(&[dep]))
    }

    fn dependencies_for_query(&self, query: &Query) -> anyhow::Result<Vec<CausalityDependency>> {
        let mut tables = Vec::new();
        let mut seen = HashSet::new();
        collect_tables(query, &mut tables);
        let mut out = Vec::new();
        for (db, table) in tables {
            let key = format!("{db}.{table}");
            if !seen.insert(key.clone()) {
                continue;
            }
            if let Ok(schema) = self.get_schema(&db, &table) {
                out.push(CausalityDependency {
                    table: key,
                    v: Some(schema.table_version),
                    view: None,
                    change_seq: None,
                    stale: None,
                });
            } else if let Some(view) = self.views.get(&TableKey {
                db: db.clone(),
                table: table.clone(),
            }) {
                out.push(CausalityDependency {
                    table: key,
                    v: None,
                    view: Some(true),
                    change_seq: Some(view.last_change_seq),
                    stale: Some(view.stale),
                });
            } else {
                anyhow::bail!("table not found: {db}.{table}");
            }
        }
        Ok(out)
    }

    fn build_column_snapshot_from_plan(&self, plan: SnapshotPlan) -> anyhow::Result<bool> {
        let snapshot = self.build_column_snapshot_internal(
            &plan.table.db,
            &plan.table.table,
            plan.columns.clone(),
            plan.snapshot_ts,
            Some((plan.build_cost, plan.benefit)),
        )?;
        let mut inserted = false;
        if let Ok(mut manager) = self.snapshots.lock() {
            inserted = manager.insert_snapshot(snapshot);
        }
        if inserted {
            self.persist_snapshots_best_effort();
        }
        Ok(inserted)
    }

    fn build_column_snapshot_internal(
        &self,
        db: &str,
        table: &str,
        requested_columns: Vec<String>,
        snapshot_ts: u64,
        stats: Option<(f64, f64)>,
    ) -> anyhow::Result<ColumnSnapshot> {
        let schema = self.get_schema(db, table)?;
        if schema.primary_key.is_empty() {
            anyhow::bail!("table has no primary key");
        }

        let columns = if requested_columns.is_empty() {
            schema.columns.iter().map(|c| c.name.clone()).collect()
        } else {
            resolve_snapshot_columns(schema, &requested_columns)?
        };

        let id = snapshot_id(db, table, snapshot_ts, &columns);

        let table_ref = BaseTableRef {
            db: db.to_string(),
            table: table.to_string(),
            r#as: None,
        };
        let (_, tdata) = self.get_table(&table_ref)?;
        let visibility_ts_ms = snapshot_ts_to_commit_ts_ms(snapshot_ts);

        let mut rows = Vec::new();
        let mut pk_index = HashMap::new();

        for entry in tdata.rows.iter() {
            if !row_visible_at(entry, Some(visibility_ts_ms)) {
                continue;
            }
            let pk = extract_pk(schema, &entry.row)?;
            let key = pk_key(&pk);
            if pk_index.contains_key(&key) {
                continue;
            }
            let values = snapshot_values(&columns, &entry.row);
            let idx = rows.len();
            rows.push(SnapshotRow { pk, values });
            pk_index.insert(key, idx);
        }

        let mut column_index = HashMap::new();
        for (idx, col) in columns.iter().enumerate() {
            column_index.insert(col.clone(), idx);
        }

        let mut snapshot = ColumnSnapshot {
            id,
            db: db.to_string(),
            table: table.to_string(),
            columns,
            pk_columns: schema.primary_key.clone(),
            snapshot_ts,
            table_version: schema.table_version,
            rows,
            pk_index,
            column_index,
            stats: SnapshotStats::default(),
            valid: true,
        };

        if let Some((build_cost, benefit)) = stats {
            snapshot.stats.build_cost = build_cost;
            snapshot.stats.benefit_score = benefit;
        }

        Ok(snapshot)
    }

    fn apply_snapshot_upserts(&self, table: &BaseTableRef, rows: &[RowObject]) -> bool {
        if rows.is_empty() {
            return false;
        }
        let schema = match self.get_schema(&table.db, &table.table) {
            Ok(schema) => schema,
            Err(_) => return false,
        };
        let key = TableKey {
            db: table.db.clone(),
            table: table.table.clone(),
        };
        if let Ok(mut manager) = self.snapshots.lock() {
            return manager.apply_upserts(&key, rows, schema.table_version);
        }
        false
    }

    fn apply_snapshot_deletes(&self, table: &BaseTableRef, pks: &[Vec<Lit>]) -> bool {
        if pks.is_empty() {
            return false;
        }
        let schema = match self.get_schema(&table.db, &table.table) {
            Ok(schema) => schema,
            Err(_) => return false,
        };
        let key = TableKey {
            db: table.db.clone(),
            table: table.table.clone(),
        };
        if let Ok(mut manager) = self.snapshots.lock() {
            return manager.apply_deletes(&key, pks, schema.table_version);
        }
        false
    }

