    #[test]
    fn snapshot_query_reads_cseg_sidecars_for_pk_filters_and_keys() -> anyhow::Result<()> {
        let dir = temp_dir("snap_reader_query");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "users",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "city".to_string(),
                    r#type: type_desc("string"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            vec![
                row(&[
                    ("id", Lit::U64 { v: 1 }),
                    (
                        "city",
                        Lit::Str {
                            v: "Oslo".to_string(),
                        },
                    ),
                ]),
                row(&[
                    ("id", Lit::U64 { v: 2 }),
                    (
                        "city",
                        Lit::Str {
                            v: "Tokyo".to_string(),
                        },
                    ),
                ]),
            ],
            None,
        )?;

        engine.build_column_snapshot(
            "app",
            "users",
            Some(vec!["city".to_string()]),
            now_micros(),
        )?;

        let key = TableKey {
            db: "app".to_string(),
            table: "users".to_string(),
        };
        if let Some(tdata) = engine.tables.get_mut(&key) {
            if let Some(entry) = tdata
                .rows
                .iter_mut()
                .find(|entry| matches!(entry.row.get("id"), Some(Lit::U64 { v }) if *v == 2))
            {
                entry.row.insert(
                    "city".to_string(),
                    Lit::Str {
                        v: "LiveCorrupt".to_string(),
                    },
                );
            }
        }
        if let Some(snapshot) = engine
            .snapshots
            .lock()
            .unwrap()
            .snapshots
            .get_mut(&key)
            .and_then(|list| list.get_mut(0))
        {
            if let Some(value) = snapshot
                .rows
                .get_mut(1)
                .and_then(|row| row.values.get_mut(0))
            {
                *value = Lit::Str {
                    v: "MemoryCorrupt".to_string(),
                };
            }
        }

        let query = base_query(
            "app",
            "users",
            vec![Expr::Col {
                col: "city".to_string(),
                table: None,
            }],
            Some(eq_expr(
                Expr::Col {
                    col: "id".to_string(),
                    table: None,
                },
                Expr::Lit {
                    lit: Lit::U64 { v: 2 },
                },
            )),
        );

        let (_cols, rows) = execute_select(&engine, &query, &[], None)?;
        assert_eq!(rows.len(), 1);
        assert_eq!(
            rows[0],
            vec![Lit::Str {
                v: "Tokyo".to_string(),
            }]
        );

        let (_cols, rows, keys) = execute_select_with_keys(&engine, &query, &[], None)?;
        assert_eq!(rows.len(), 1);
        assert_eq!(
            rows[0],
            vec![Lit::Str {
                v: "Tokyo".to_string(),
            }]
        );
        assert_eq!(keys, vec![vec![Lit::U64 { v: 2 }]]);

        let hits = engine
            .snapshots
            .lock()
            .unwrap()
            .snapshots
            .get(&key)
            .unwrap()[0]
            .stats
            .hits;
        assert!(hits >= 2);

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn snapshot_build_writes_cseg_manifest_and_respects_snapshot_ts() -> anyhow::Result<()> {
        let dir = temp_dir("snap_cseg_build");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "users",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "city".to_string(),
                    r#type: type_desc("string"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            vec![
                row(&[
                    ("id", Lit::U64 { v: 1 }),
                    (
                        "city",
                        Lit::Str {
                            v: "Oslo".to_string(),
                        },
                    ),
                ]),
                row(&[
                    ("id", Lit::U64 { v: 2 }),
                    (
                        "city",
                        Lit::Str {
                            v: "Tokyo".to_string(),
                        },
                    ),
                ]),
            ],
            None,
        )?;

        let snapshot_ts = now_micros();
        std::thread::sleep(std::time::Duration::from_millis(5));

        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            vec![row(&[
                ("id", Lit::U64 { v: 3 }),
                (
                    "city",
                    Lit::Str {
                        v: "Paris".to_string(),
                    },
                ),
            ])],
            None,
        )?;

        engine.data_delete(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            &eq_expr(
                Expr::Col {
                    col: "id".to_string(),
                    table: None,
                },
                Expr::Lit {
                    lit: Lit::U64 { v: 2 },
                },
            ),
            None,
            &[],
        )?;

        engine.build_column_snapshot(
            "app",
            "users",
            Some(vec!["id".to_string(), "city".to_string()]),
            snapshot_ts,
        )?;

        let list: Vec<ColumnSnapshotDisk> =
            load_json(&dir.join("snapshots.json")).unwrap_or_default();
        assert_eq!(list.len(), 1);

        let snapshot = &list[0];
        let snapshot_dir = dir.join("snapshots").join(snapshot_dir_name(&snapshot.id));
        assert!(snapshot_dir.exists());

        let manifest: ColumnSnapshotManifestDisk =
            load_json(&snapshot_dir.join("manifest.json")).expect("missing snapshot manifest");
        assert_eq!(manifest.row_count, 2);
        assert_eq!(manifest.segments.len(), 2);

        let id_segment = manifest
            .segments
            .iter()
            .find(|segment| segment.column == "id" && segment.is_pk)
            .expect("missing pk segment");
        let city_segment = manifest
            .segments
            .iter()
            .find(|segment| segment.column == "city" && !segment.is_pk)
            .expect("missing city segment");

        let ids = read_snapshot_cseg(&snapshot_dir.join(&id_segment.file))?;
        let cities = read_snapshot_cseg(&snapshot_dir.join(&city_segment.file))?;
        assert_eq!(ids.values, vec![Lit::U64 { v: 1 }, Lit::U64 { v: 2 }]);
        assert_eq!(
            cities.values,
            vec![
                Lit::Str {
                    v: "Oslo".to_string(),
                },
                Lit::Str {
                    v: "Tokyo".to_string(),
                },
            ]
        );

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn index_advisor_synthesizes_candidate() -> anyhow::Result<()> {
        let dir = temp_dir("index_advisor");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "users",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "city".to_string(),
                    r#type: type_desc("string"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "created_at".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "name".to_string(),
                    r#type: type_desc("string"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let rows = vec![
            row(&[
                ("id", Lit::U64 { v: 1 }),
                (
                    "city",
                    Lit::Str {
                        v: "Oslo".to_string(),
                    },
                ),
                ("created_at", Lit::U64 { v: 10 }),
                (
                    "name",
                    Lit::Str {
                        v: "Ava".to_string(),
                    },
                ),
            ]),
            row(&[
                ("id", Lit::U64 { v: 2 }),
                (
                    "city",
                    Lit::Str {
                        v: "Oslo".to_string(),
                    },
                ),
                ("created_at", Lit::U64 { v: 11 }),
                (
                    "name",
                    Lit::Str {
                        v: "Bo".to_string(),
                    },
                ),
            ]),
        ];
        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            rows,
            None,
        )?;

        let mut query = base_query(
            "app",
            "users",
            vec![
                Expr::Col {
                    col: "id".to_string(),
                    table: None,
                },
                Expr::Col {
                    col: "name".to_string(),
                    table: None,
                },
            ],
            Some(eq_expr(
                Expr::Col {
                    col: "city".to_string(),
                    table: None,
                },
                Expr::Param { param: 0 },
            )),
        );
        query.order_by = vec![OrderBy {
            expr: Expr::Col {
                col: "created_at".to_string(),
                table: None,
            },
            dir: None,
        }];

        let (_cols, rows) = execute_select(
            &engine,
            &query,
            &[Lit::Str {
                v: "Oslo".to_string(),
            }],
            None,
        )?;
        assert_eq!(rows.len(), 2);

        let result = engine.advisor_index_synthesize(AdvisorIndexSynthesizeParams {
            table: BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            limit: Some(5),
            min_queries: Some(1),
            min_rows: Some(1),
        })?;
        assert!(!result.suggestions.is_empty());
        let suggestion = &result.suggestions[0];
        assert!(suggestion.id.is_some());
        assert_eq!(
            suggestion.columns,
            vec!["city".to_string(), "created_at".to_string()]
        );
        assert!(suggestion.include.contains(&"name".to_string()));
        let dependency = suggestion.dependency.as_ref().expect("dependency capture");
        assert_eq!(dependency.predicate_columns, vec!["city".to_string()]);
        assert_eq!(dependency.equality_columns, vec!["city".to_string()]);
        assert!(dependency.range_columns.is_empty());
        assert_eq!(dependency.range_shape, "none");
        assert_eq!(dependency.order_by_columns, vec!["created_at".to_string()]);
        assert!(dependency.projection_columns.contains(&"name".to_string()));

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

