    #[test]
    fn advisor_index_apply_builds_secondary_index() -> anyhow::Result<()> {
        let dir = temp_dir("index_apply_builds");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "users",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "city".to_string(),
                    r#type: type_desc("string"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            vec![
                row(&[
                    ("id", Lit::U64 { v: 1 }),
                    (
                        "city",
                        Lit::Str {
                            v: "Oslo".to_string(),
                        },
                    ),
                ]),
                row(&[
                    ("id", Lit::U64 { v: 2 }),
                    (
                        "city",
                        Lit::Str {
                            v: "Oslo".to_string(),
                        },
                    ),
                ]),
            ],
            None,
        )?;

        let apply = engine.advisor_index_apply(AdvisorIndexApplyParams {
            table: BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            columns: vec!["city".to_string()],
            include: Vec::new(),
            note: None,
        })?;
        assert!(apply.accepted);
        assert_eq!(apply.status.as_deref(), Some("queued"));
        engine.advisor_complete_index_apply(&apply.action_id, None)?;

        let (schema, tdata) = engine.get_table(&BaseTableRef {
            db: "app".to_string(),
            table: "users".to_string(),
            r#as: None,
        })?;
        let mut filters = HashMap::new();
        filters.insert(
            "city".to_string(),
            Lit::Str {
                v: "Oslo".to_string(),
            },
        );
        let candidates = secondary_index_candidates(schema, tdata, &filters).unwrap_or_default();
        assert_eq!(candidates.len(), 2);

        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            vec![row(&[
                ("id", Lit::U64 { v: 3 }),
                (
                    "city",
                    Lit::Str {
                        v: "Oslo".to_string(),
                    },
                ),
            ])],
            None,
        )?;
        let (schema, tdata) = engine.get_table(&BaseTableRef {
            db: "app".to_string(),
            table: "users".to_string(),
            r#as: None,
        })?;
        let candidates = secondary_index_candidates(schema, tdata, &filters).unwrap_or_default();
        assert_eq!(candidates.len(), 3);

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn advisor_index_apply_failure_rolls_back_registered_index() -> anyhow::Result<()> {
        let dir = temp_dir("index_apply_failure_rolls_back");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "users",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "city".to_string(),
                    r#type: type_desc("string"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            vec![row(&[
                ("id", Lit::U64 { v: 1 }),
                (
                    "city",
                    Lit::Str {
                        v: "Oslo".to_string(),
                    },
                ),
            ])],
            None,
        )?;

        let apply = engine.advisor_index_apply(AdvisorIndexApplyParams {
            table: BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            columns: vec!["city".to_string()],
            include: Vec::new(),
            note: Some("force failure".to_string()),
        })?;
        assert_eq!(apply.status.as_deref(), Some("queued"));
        assert!(engine
            .advisor_complete_index_apply(&apply.action_id, Some("forced failure"))
            .is_err());

        let history = engine.advisor_history(AdvisorHistoryParams {
            table: Some(BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            }),
            limit: Some(10),
        })?;
        let failed = history
            .entries
            .iter()
            .find(|entry| entry.id == apply.action_id)
            .expect("missing failed advisor history entry");
        assert_eq!(failed.status.as_deref(), Some("failed"));
        assert_eq!(failed.rollback_status.as_deref(), Some("rolled_back"));

        let (schema, tdata) = engine.get_table(&BaseTableRef {
            db: "app".to_string(),
            table: "users".to_string(),
            r#as: None,
        })?;
        let mut filters = HashMap::new();
        filters.insert(
            "city".to_string(),
            Lit::Str {
                v: "Oslo".to_string(),
            },
        );
        let candidates = secondary_index_candidates(schema, tdata, &filters).unwrap_or_default();
        assert!(candidates.is_empty());

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn cdc_query_subscription_emits_invalidation_with_etag() -> anyhow::Result<()> {
        let dir = temp_dir("cdc_query_subscription");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "events",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "data".to_string(),
                    r#type: type_desc("string"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let query = base_query(
            "app",
            "events",
            vec![
                Expr::Col {
                    col: "id".to_string(),
                    table: None,
                },
                Expr::Col {
                    col: "data".to_string(),
                    table: None,
                },
            ],
            None,
        );
        let prepared = engine.query_prepare(query.clone())?;

        let mut subs = Subscriptions::default();
        let subscribe = engine.cdc_subscribe_query(&mut subs, &prepared.id, &[])?;

        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "events".to_string(),
                r#as: None,
            },
            vec![row(&[
                ("id", Lit::U64 { v: 1 }),
                (
                    "data",
                    Lit::Str {
                        v: "hello".to_string(),
                    },
                ),
            ])],
            None,
        )?;

        let poll = engine.cdc_poll(&subs, &subscribe.sub_id, subscribe.offset, 10)?;
        assert_eq!(poll.events.len(), 1);
        let event = &poll.events[0];
        assert_eq!(event.op, "invalidate");
        assert_eq!(event.query_id.as_deref(), Some(prepared.id.as_str()));
        assert_eq!(event.db, "app");
        assert_eq!(event.table, "events");
        assert!(event.before.is_none());
        assert!(event.after.is_none());

        let select = engine.query_select(
            &query,
            &[],
            ResultFormat::RowsJson,
            true,
            None,
            None,
            None,
            false,
            None,
        )?;
        assert_eq!(event.etag.as_deref(), select.etag.as_deref());
        assert!(event.commit_ts_ms > 0);
        assert_eq!(event.lsn, Some(1));

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

