    #[test]
    fn cdc_poll_requires_resnapshot_after_retention_horizon() -> anyhow::Result<()> {
        let dir = temp_dir("cdc_resnapshot_horizon");
        let mut engine = Engine::open(&dir)?;
        engine.cdc_retention_events = 2;
        engine.create_table(
            "app",
            "events",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "data".to_string(),
                    r#type: type_desc("string"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let mut subs = Subscriptions::default();
        let subscribe = engine.cdc_subscribe_table(&mut subs, "app", "events")?;

        for (id, value) in [(1u64, "one"), (2u64, "two"), (3u64, "three")] {
            engine.data_insert(
                &BaseTableRef {
                    db: "app".to_string(),
                    table: "events".to_string(),
                    r#as: None,
                },
                vec![row(&[
                    ("id", Lit::U64 { v: id }),
                    (
                        "data",
                        Lit::Str {
                            v: value.to_string(),
                        },
                    ),
                ])],
                None,
            )?;
        }

        let poll = engine.cdc_poll(&subs, &subscribe.sub_id, subscribe.offset, 10)?;
        assert!(poll.events.is_empty());
        assert!(poll.resnapshot_required);
        assert_eq!(poll.earliest_offset, 2);
        assert_eq!(poll.latest_offset, 3);
        assert_eq!(poll.next_offset, 1);
        assert_eq!(poll.resnapshot_from_offset, Some(1));
        assert_eq!(
            poll.resnapshot_reason.as_deref(),
            Some("wal_horizon_exceeded")
        );

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn cdc_durable_cursor_survives_restart() -> anyhow::Result<()> {
        let dir = temp_dir("cdc_durable_cursor_restart");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "events",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "data".to_string(),
                    r#type: type_desc("string"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let mut subs = Subscriptions::default();
        let subscribe = engine.cdc_subscribe_table(&mut subs, "app", "events")?;
        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "events".to_string(),
                r#as: None,
            },
            vec![row(&[
                ("id", Lit::U64 { v: 1 }),
                (
                    "data",
                    Lit::Str {
                        v: "one".to_string(),
                    },
                ),
            ])],
            None,
        )?;
        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "events".to_string(),
                r#as: None,
            },
            vec![row(&[
                ("id", Lit::U64 { v: 2 }),
                (
                    "data",
                    Lit::Str {
                        v: "two".to_string(),
                    },
                ),
            ])],
            None,
        )?;

        let first_batch = engine.cdc_poll(&subs, &subscribe.sub_id, subscribe.offset, 1)?;
        assert_eq!(first_batch.events.len(), 1);
        assert_eq!(first_batch.events[0].seq, 1);
        engine.cdc_ack(&mut subs, &subscribe.sub_id, first_batch.next_offset)?;
        assert!(dir.join("cdc_subscriptions.json").exists());

        let reopened = Engine::open(&dir)?;
        let mut reopened_subs = reopened.load_cdc_subscriptions_best_effort();
        let resumed = reopened.cdc_poll(&reopened_subs, &subscribe.sub_id, 0, 10)?;
        assert_eq!(resumed.events.len(), 1);
        assert_eq!(resumed.events[0].seq, 2);

        reopened.cdc_close(&mut reopened_subs, &subscribe.sub_id)?;
        assert!(!dir.join("cdc_subscriptions.json").exists());

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn cdc_file_sink_drain_writes_ndjson_and_advances_cursor() -> anyhow::Result<()> {
        let dir = temp_dir("cdc_file_sink_drain");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "events",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "data".to_string(),
                    r#type: type_desc("string"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let sink_path = dir.join("sink").join("events.ndjson");
        let options = CdcSubscriptionOptions {
            sink: Some(CdcSinkConfig::File {
                path: sink_path.to_string_lossy().into_owned(),
            }),
            ..Default::default()
        };
        let mut subs = Subscriptions::default();
        let subscribe =
            engine.cdc_subscribe_table_with_options(&mut subs, "app", "events", options)?;

        let insert = |engine: &mut Engine, id: u64, data: &str| -> anyhow::Result<()> {
            engine.data_insert(
                &BaseTableRef {
                    db: "app".to_string(),
                    table: "events".to_string(),
                    r#as: None,
                },
                vec![row(&[
                    ("id", Lit::U64 { v: id }),
                    (
                        "data",
                        Lit::Str {
                            v: data.to_string(),
                        },
                    ),
                ])],
                None,
            )?;
            Ok(())
        };

        insert(&mut engine, 1, "one")?;
        insert(&mut engine, 2, "two")?;

        let drained = engine.cdc_sink_drain(&mut subs, &subscribe.sub_id, 10)?;
        assert_eq!(drained.delivered, 2);
        assert_eq!(drained.sink_offset, 2);

        let contents = fs::read_to_string(&sink_path)?;
        let lines: Vec<&str> = contents.lines().collect();
        assert_eq!(lines.len(), 2);
        let first: serde_json::Value = serde_json::from_str(lines[0])?;
        assert_eq!(first["op"], "insert");
        assert_eq!(first["seq"], 1);
        let second: serde_json::Value = serde_json::from_str(lines[1])?;
        assert_eq!(second["seq"], 2);

        // Cursor advanced: a second drain with no new events delivers nothing.
        let drained_again = engine.cdc_sink_drain(&mut subs, &subscribe.sub_id, 10)?;
        assert_eq!(drained_again.delivered, 0);
        assert_eq!(drained_again.sink_offset, 2);
        assert_eq!(fs::read_to_string(&sink_path)?.lines().count(), 2);

        // The sink cursor is durable across a restart.
        insert(&mut engine, 3, "three")?;
        let reopened = Engine::open(&dir)?;
        let mut reopened_subs = reopened.load_cdc_subscriptions_best_effort();
        let drained_after_restart =
            reopened.cdc_sink_drain(&mut reopened_subs, &subscribe.sub_id, 10)?;
        assert_eq!(drained_after_restart.delivered, 1);
        assert_eq!(drained_after_restart.sink_offset, 3);
        assert_eq!(fs::read_to_string(&sink_path)?.lines().count(), 3);

        // A subscription without a sink rejects drains.
        let plain = engine.cdc_subscribe_table(&mut subs, "app", "events")?;
        let err = engine
            .cdc_sink_drain(&mut subs, &plain.sub_id, 10)
            .unwrap_err()
            .to_string();
        assert!(err.contains("no sink"), "unexpected error: {err}");

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn encryption_status_persists_profiles_and_audit_across_restart() -> anyhow::Result<()> {
        let dir = temp_dir("encryption_state_restart");
        let mut engine = Engine::open(&dir)?;
        let master_key_b64 =
            BASE64_STANDARD.encode([7u8; skeindb_core::encryption::ENCRYPTION_MASTER_KEY_LEN]);

        engine
            .settings_encryption_register_key(
                skeindb_skeinql::methods::SettingsEncryptionRegisterKeyParams {
                    db: "app".to_string(),
                    key_id: "k1".to_string(),
                    master_key_b64: master_key_b64.clone(),
                    make_active: true,
                },
            )
            .map_err(anyhow::Error::msg)?;
        engine
            .settings_encryption_set_mode(
                skeindb_skeinql::methods::SettingsEncryptionSetModeParams {
                    db: "app".to_string(),
                    mode: "enc_mle_db".to_string(),
                },
            )
            .map_err(anyhow::Error::msg)?;

        let disk: EncryptionStateDisk = load_json(&dir.join("encryption.json"))
            .ok_or_else(|| anyhow::anyhow!("missing encryption.json"))?;
        assert_eq!(disk.format_version, ENCRYPTION_STATE_FORMAT_VERSION);
        assert_eq!(disk.databases.len(), 1);
        assert_eq!(disk.databases[0].db_id, "app");
        assert_eq!(
            disk.databases[0].mode.as_str(),
            skeindb_core::encryption::EncryptionMode::EncMleDb.as_str()
        );
        assert_eq!(disk.databases[0].active_key_id.as_deref(), Some("k1"));

        drop(engine);

        let mut reopened = Engine::open(&dir)?;
        let status = reopened.settings_encryption_status(
            skeindb_skeinql::methods::SettingsEncryptionStatusParams {
                db: Some("app".to_string()),
            },
        );
        let databases = status
            .get("databases")
            .and_then(|value| value.as_array())
            .cloned()
            .unwrap_or_default();
        assert_eq!(databases.len(), 1);
        assert_eq!(
            databases[0].get("db").and_then(|value| value.as_str()),
            Some("app")
        );
        assert_eq!(
            databases[0].get("mode").and_then(|value| value.as_str()),
            Some(skeindb_core::encryption::EncryptionMode::EncMleDb.as_str())
        );
        assert_eq!(
            databases[0]
                .get("active_key_id")
                .and_then(|value| value.as_str()),
            Some("k1")
        );
        assert_eq!(
            databases[0]
                .get("registered_key_ids")
                .and_then(|value| value.as_array())
                .map(|items| items.len()),
            Some(0)
        );

        let audit_actions = status
            .get("recent_audit")
            .and_then(|value| value.as_array())
            .cloned()
            .unwrap_or_default()
            .into_iter()
            .filter_map(|entry| {
                entry
                    .get("action")
                    .and_then(|value| value.as_str())
                    .map(|value| value.to_string())
            })
            .collect::<Vec<_>>();
        assert!(audit_actions.iter().any(|action| action == "register_key"));
        assert!(audit_actions.iter().any(|action| action == "set_mode"));

        reopened
            .settings_encryption_register_key(
                skeindb_skeinql::methods::SettingsEncryptionRegisterKeyParams {
                    db: "app".to_string(),
                    key_id: "k1".to_string(),
                    master_key_b64,
                    make_active: false,
                },
            )
            .map_err(anyhow::Error::msg)?;
        let rehydrated = reopened.settings_encryption_status(
            skeindb_skeinql::methods::SettingsEncryptionStatusParams {
                db: Some("app".to_string()),
            },
        );
        assert_eq!(
            rehydrated["databases"][0]["registered_key_ids"]
                .as_array()
                .map(|items| items.len()),
            Some(1)
        );
        assert_eq!(
            rehydrated["databases"][0]["active_key_id"].as_str(),
            Some("k1")
        );

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn encrypted_at_rest_cells_roundtrip_and_lock_without_key() -> anyhow::Result<()> {
        use skeindb_core::encryption::ENCRYPTION_MASTER_KEY_LEN;

        let dir = temp_dir("encrypted_at_rest_roundtrip");
        let master_key_b64 = BASE64_STANDARD.encode([9u8; ENCRYPTION_MASTER_KEY_LEN]);
        let secret_a = "top-secret-payload-A";
        let secret_b = "top-secret-payload-B";

        {
            let mut engine = Engine::open_with_storage_mode_name(&dir, "hybrid")?;
            engine
                .settings_encryption_register_key(
                    skeindb_skeinql::methods::SettingsEncryptionRegisterKeyParams {
                        db: "app".to_string(),
                        key_id: "k1".to_string(),
                        master_key_b64: master_key_b64.clone(),
                        make_active: true,
                    },
                )
                .map_err(anyhow::Error::msg)?;
            engine
                .settings_encryption_set_mode(
                    skeindb_skeinql::methods::SettingsEncryptionSetModeParams {
                        db: "app".to_string(),
                        mode: "enc_random".to_string(),
                    },
                )
                .map_err(anyhow::Error::msg)?;

            seed_events_table(&mut engine, secret_a, secret_b)?;

            // The plaintext secret must not appear anywhere in the on-disk table file.
            engine.flush_dirty_tables()?;
            let table_bytes = fs::read(engine.table_path("app", "events"))
                .or_else(|_| fs::read(engine.table_segment_path("app", "events")))?;
            assert!(
                !contains_subslice(&table_bytes, secret_a.as_bytes()),
                "plaintext secret leaked into the on-disk table file"
            );

            // The on-disk rows must carry encrypted cell payloads.
            let disk: TableRowsDisk = load_json(&engine.table_path("app", "events"))
                .ok_or_else(|| anyhow::anyhow!("missing events table json"))?;
            assert_eq!(disk.format_version, TABLE_ROWS_FORMAT_VERSION);
            assert!(disk_rows_contain_encrypted_cells(&disk));

            // In-memory reads transparently decrypt.
            let rows = &engine
                .tables
                .get(&TableKey {
                    db: "app".to_string(),
                    table: "events".to_string(),
                })
                .expect("events table present")
                .rows;
            assert_eq!(rows.len(), 2);
            assert!(rows.iter().any(|entry| matches!(
                entry.row.get("payload"),
                Some(Lit::Str { v }) if v == secret_a
            )));
        }

        // Reopen WITHOUT registering the key: the table must be locked (loaded empty) and
        // writes/persist must be refused so the ciphertext is never overwritten.
        {
            let engine = Engine::open_with_storage_mode_name(&dir, "hybrid")?;
            let key = TableKey {
                db: "app".to_string(),
                table: "events".to_string(),
            };
            assert!(engine.encrypted_locked_tables.contains(&key));
            assert_eq!(
                engine.tables.get(&key).map(|t| t.rows.len()).unwrap_or(0),
                0
            );
            let err = engine
                .persist_table("app", "events")
                .expect_err("persisting a locked table must fail");
            assert!(err.to_string().contains("encryption key required"));
        }

        // Reopen and register the key: the encrypted table unlocks and decrypts.
        {
            let mut engine = Engine::open_with_storage_mode_name(&dir, "hybrid")?;
            engine
                .settings_encryption_register_key(
                    skeindb_skeinql::methods::SettingsEncryptionRegisterKeyParams {
                        db: "app".to_string(),
                        key_id: "k1".to_string(),
                        master_key_b64: master_key_b64.clone(),
                        make_active: true,
                    },
                )
                .map_err(anyhow::Error::msg)?;
            let key = TableKey {
                db: "app".to_string(),
                table: "events".to_string(),
            };
            assert!(!engine.encrypted_locked_tables.contains(&key));
            let rows = &engine.tables.get(&key).expect("events present").rows;
            assert_eq!(rows.len(), 2);
            assert!(rows.iter().any(|entry| matches!(
                entry.row.get("payload"),
                Some(Lit::Str { v }) if v == secret_b
            )));
        }

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn encrypted_at_rest_mle_is_deterministic_for_equal_plaintext() -> anyhow::Result<()> {
        use skeindb_core::encryption::ENCRYPTION_MASTER_KEY_LEN;

        let dir = temp_dir("encrypted_at_rest_mle");
        let master_key_b64 = BASE64_STANDARD.encode([3u8; ENCRYPTION_MASTER_KEY_LEN]);
        let mut engine = Engine::open_with_storage_mode_name(&dir, "hybrid")?;
        engine
            .settings_encryption_register_key(
                skeindb_skeinql::methods::SettingsEncryptionRegisterKeyParams {
                    db: "app".to_string(),
                    key_id: "k1".to_string(),
                    master_key_b64,
                    make_active: true,
                },
            )
            .map_err(anyhow::Error::msg)?;
        engine
            .settings_encryption_set_mode(
                skeindb_skeinql::methods::SettingsEncryptionSetModeParams {
                    db: "app".to_string(),
                    mode: "enc_mle_db".to_string(),
                },
            )
            .map_err(anyhow::Error::msg)?;

        // Both rows share the same payload; MLE mode must produce identical ciphertext.
        seed_events_table(&mut engine, "same-secret", "same-secret")?;

        engine.flush_dirty_tables()?;
        let disk: TableRowsDisk = load_json(&engine.table_path("app", "events"))
            .ok_or_else(|| anyhow::anyhow!("missing events table json"))?;
        let env_b64s: Vec<String> = disk
            .rows
            .iter()
            .filter_map(|row| {
                row.row
                    .get("payload")
                    .and_then(decode_encrypted_cell_payload)
                    .map(|p| p.env_b64)
            })
            .collect();
        assert_eq!(env_b64s.len(), 2);
        assert_eq!(
            env_b64s[0], env_b64s[1],
            "MLE ciphertext must be deterministic"
        );

        // And the values still decrypt correctly in memory.
        let rows = &engine
            .tables
            .get(&TableKey {
                db: "app".to_string(),
                table: "events".to_string(),
            })
            .expect("events present")
            .rows;
        assert!(rows.iter().all(|entry| matches!(
            entry.row.get("payload"),
            Some(Lit::Str { v }) if v == "same-secret"
        )));

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn reencrypt_table_reseals_rows_under_active_key_after_rotation() -> anyhow::Result<()> {
        use skeindb_core::encryption::{EncryptionEnvelope, ENCRYPTION_MASTER_KEY_LEN};

        // Read the distinct key ids that the on-disk `payload` envelopes are sealed under.
        fn payload_key_ids(disk: &TableRowsDisk) -> Vec<Option<String>> {
            disk.rows
                .iter()
                .filter_map(|row| {
                    let payload = decode_encrypted_cell_payload(row.row.get("payload")?)?;
                    let stored = BASE64_STANDARD.decode(payload.env_b64.as_bytes()).ok()?;
                    let env = EncryptionEnvelope::from_stored_bytes(&stored).ok()?;
                    Some(env.key_id)
                })
                .collect()
        }

        let dir = temp_dir("reencrypt_table_rotation");
        let secret_a = "rotate-secret-A";
        let secret_b = "rotate-secret-B";
        let k1 = BASE64_STANDARD.encode([5u8; ENCRYPTION_MASTER_KEY_LEN]);
        let k2 = BASE64_STANDARD.encode([6u8; ENCRYPTION_MASTER_KEY_LEN]);

        let mut engine = Engine::open_with_storage_mode_name(&dir, "hybrid")?;
        engine
            .settings_encryption_register_key(
                skeindb_skeinql::methods::SettingsEncryptionRegisterKeyParams {
                    db: "app".to_string(),
                    key_id: "k1".to_string(),
                    master_key_b64: k1,
                    make_active: true,
                },
            )
            .map_err(anyhow::Error::msg)?;
        engine
            .settings_encryption_set_mode(
                skeindb_skeinql::methods::SettingsEncryptionSetModeParams {
                    db: "app".to_string(),
                    mode: "enc_random".to_string(),
                },
            )
            .map_err(anyhow::Error::msg)?;
        seed_events_table(&mut engine, secret_a, secret_b)?;

        // Rows are initially sealed under k1.
        engine.flush_dirty_tables()?;
        let disk: TableRowsDisk = load_json(&engine.table_path("app", "events"))
            .ok_or_else(|| anyhow::anyhow!("missing events table json"))?;
        assert!(disk_rows_contain_encrypted_cells(&disk));
        assert!(payload_key_ids(&disk)
            .iter()
            .all(|k| k.as_deref() == Some("k1")));

        // Register and rotate to k2. Rotation only flips the active key; existing rows are
        // still sealed under k1 until a re-encryption sweep runs.
        engine
            .settings_encryption_register_key(
                skeindb_skeinql::methods::SettingsEncryptionRegisterKeyParams {
                    db: "app".to_string(),
                    key_id: "k2".to_string(),
                    master_key_b64: k2,
                    make_active: false,
                },
            )
            .map_err(anyhow::Error::msg)?;
        engine
            .settings_encryption_rotate_key(
                skeindb_skeinql::methods::SettingsEncryptionRotateKeyParams {
                    db: "app".to_string(),
                    new_key_id: "k2".to_string(),
                },
            )
            .map_err(anyhow::Error::msg)?;
        let pre_sweep: TableRowsDisk = load_json(&engine.table_path("app", "events"))
            .ok_or_else(|| anyhow::anyhow!("missing events table json"))?;
        assert!(payload_key_ids(&pre_sweep)
            .iter()
            .all(|k| k.as_deref() == Some("k1")));

        // Sweep: re-encrypt the table under the active key (k2).
        let result = engine
            .settings_encryption_reencrypt_table(
                skeindb_skeinql::methods::SettingsEncryptionReencryptTableParams {
                    db: "app".to_string(),
                    table: "events".to_string(),
                },
            )
            .map_err(anyhow::Error::msg)?;
        assert_eq!(result["ok"], serde_json::json!(true));
        assert_eq!(result["encrypted"], serde_json::json!(true));
        assert_eq!(result["rewrote"], serde_json::json!(true));
        assert_eq!(result["rows"], serde_json::json!(2));
        assert_eq!(result["active_key_id"], serde_json::json!("k2"));

        // On-disk envelopes are now sealed under k2.
        let post_sweep: TableRowsDisk = load_json(&engine.table_path("app", "events"))
            .ok_or_else(|| anyhow::anyhow!("missing events table json"))?;
        assert!(payload_key_ids(&post_sweep)
            .iter()
            .all(|k| k.as_deref() == Some("k2")));

        // Values still decrypt transparently after re-opening with both keys removed but k2
        // registered (proves the new envelopes are independent of k1).
        let rows = &engine
            .tables
            .get(&TableKey {
                db: "app".to_string(),
                table: "events".to_string(),
            })
            .expect("events present")
            .rows;
        assert!(rows.iter().any(|entry| matches!(
            entry.row.get("payload"),
            Some(Lit::Str { v }) if v == secret_a
        )));

        // A table in a database without active encryption is a no-op (no rewrite).
        engine.create_table(
            "plain",
            "notes",
            vec![ColumnSchema {
                name: "id".to_string(),
                r#type: type_desc("u64"),
                nullable: false,
                auto_increment: false,
            }],
            vec!["id".to_string()],
            false,
            None,
        )?;
        let noop = engine
            .settings_encryption_reencrypt_table(
                skeindb_skeinql::methods::SettingsEncryptionReencryptTableParams {
                    db: "plain".to_string(),
                    table: "notes".to_string(),
                },
            )
            .map_err(anyhow::Error::msg)?;
        assert_eq!(noop["encrypted"], serde_json::json!(false));
        assert_eq!(noop["rewrote"], serde_json::json!(false));

        // Unknown table is rejected.
        let err = engine
            .settings_encryption_reencrypt_table(
                skeindb_skeinql::methods::SettingsEncryptionReencryptTableParams {
                    db: "app".to_string(),
                    table: "missing".to_string(),
                },
            )
            .unwrap_err();
        assert!(err.contains("table not found"), "unexpected error: {err}");

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn cdc_pause_persists_and_horizon_loss_still_requires_resnapshot() -> anyhow::Result<()> {
        let dir = temp_dir("cdc_pause_backpressure");
        let mut engine = Engine::open(&dir)?;
        engine.set_cdc_retention_events_for_test(2);
        engine.create_table(
            "app",
            "events",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "data".to_string(),
                    r#type: type_desc("string"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let mut subs = Subscriptions::default();
        let subscribe = engine.cdc_subscribe_table(&mut subs, "app", "events")?;
        let paused = engine.cdc_pause(&mut subs, &subscribe.sub_id)?;
        assert!(paused.paused);
        assert_eq!(paused.backpressure.state, "paused");

        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "events".to_string(),
                r#as: None,
            },
            vec![row(&[
                ("id", Lit::U64 { v: 1 }),
                (
                    "data",
                    Lit::Str {
                        v: "one".to_string(),
                    },
                ),
            ])],
            None,
        )?;

        let paused_poll = engine.cdc_poll(&subs, &subscribe.sub_id, subscribe.offset, 10)?;
        assert!(paused_poll.events.is_empty());
        assert_eq!(paused_poll.next_offset, subscribe.offset);
        assert_eq!(paused_poll.backpressure.state, "paused");
        assert!(paused_poll.backpressure.paused);

        let mut reopened = Engine::open(&dir)?;
        reopened.set_cdc_retention_events_for_test(2);
        let mut reopened_subs = reopened.load_cdc_subscriptions_best_effort();
        let reopened_poll = reopened.cdc_poll(&reopened_subs, &subscribe.sub_id, 0, 10)?;
        assert!(reopened_poll.events.is_empty());
        assert_eq!(reopened_poll.backpressure.state, "paused");
        assert!(reopened_poll.backpressure.paused);

        for (id, value) in [(2u64, "two"), (3u64, "three")] {
            reopened.data_insert(
                &BaseTableRef {
                    db: "app".to_string(),
                    table: "events".to_string(),
                    r#as: None,
                },
                vec![row(&[
                    ("id", Lit::U64 { v: id }),
                    (
                        "data",
                        Lit::Str {
                            v: value.to_string(),
                        },
                    ),
                ])],
                None,
            )?;
        }

        let overflow_poll = reopened.cdc_poll(&reopened_subs, &subscribe.sub_id, 0, 10)?;
        assert!(overflow_poll.events.is_empty());
        assert!(overflow_poll.resnapshot_required);
        assert_eq!(overflow_poll.backpressure.state, "resnapshot_required");
        assert!(overflow_poll.backpressure.paused);

        let resumed = reopened.cdc_resume(&mut reopened_subs, &subscribe.sub_id)?;
        assert!(!resumed.paused);
        assert_eq!(resumed.backpressure.state, "resnapshot_required");

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn cdc_runtime_stats_snapshot_reports_lag_and_retention() -> anyhow::Result<()> {
        let dir = temp_dir("cdc_runtime_stats");
        let mut engine = Engine::open(&dir)?;
        engine.cdc_retention_events = 2;
        engine.create_table(
            "app",
            "events",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "payload".to_string(),
                    r#type: type_desc("str"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let mut subs = Subscriptions::default();
        let subscribe = engine.cdc_subscribe_table(&mut subs, "app", "events")?;
        assert_eq!(subscribe.offset, 0);

        for id in 1..=3 {
            engine.data_insert(
                &BaseTableRef {
                    db: "app".to_string(),
                    table: "events".to_string(),
                    r#as: None,
                },
                vec![row(&[
                    ("id", Lit::U64 { v: id }),
                    (
                        "payload",
                        Lit::Str {
                            v: format!("event-{id}"),
                        },
                    ),
                ])],
                None,
            )?;
        }

        let stats = engine.cdc_runtime_stats_snapshot(&subs);
        assert_eq!(stats.active_subscriptions, 1);
        assert_eq!(stats.table_subscriptions, 1);
        assert_eq!(stats.query_subscriptions, 0);
        assert_eq!(stats.total_lag, 3);
        assert_eq!(stats.max_lag, 3);
        assert_eq!(stats.resnapshot_subscriptions, 1);
        assert_eq!(stats.paused_subscriptions, 0);
        assert_eq!(stats.pressured_subscriptions, 0);
        assert_eq!(stats.throttle_recommended_subscriptions, 0);
        assert_eq!(stats.earliest_offset, 2);
        assert_eq!(stats.latest_offset, 3);
        assert_eq!(stats.retained_events, 2);
        assert_eq!(stats.retention_limit, 2);
        assert_eq!(stats.dropped_events_total, 1);
        assert_eq!(stats.warn_lag, 1);
        assert_eq!(stats.throttle_lag, 2);
        assert_eq!(stats.min_remaining_until_resnapshot, 0);

        engine.cdc_pause(&mut subs, &subscribe.sub_id)?;
        let paused_stats = engine.cdc_runtime_stats_snapshot(&subs);
        assert_eq!(paused_stats.paused_subscriptions, 1);
        assert_eq!(paused_stats.pressured_subscriptions, 0);
        assert_eq!(paused_stats.throttle_recommended_subscriptions, 0);

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn mysql_compat_indexes_seed_secondary_index_candidates() -> anyhow::Result<()> {
        let dir = temp_dir("mysql_compat_secondary_index_seed");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "users",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "city".to_string(),
                    r#type: type_desc("str"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let table = BaseTableRef {
            db: "app".to_string(),
            table: "users".to_string(),
            r#as: None,
        };
        engine.data_insert(
            &table,
            vec![
                row(&[
                    ("id", Lit::U64 { v: 1 }),
                    (
                        "city",
                        Lit::Str {
                            v: "Oslo".to_string(),
                        },
                    ),
                ]),
                row(&[
                    ("id", Lit::U64 { v: 2 }),
                    (
                        "city",
                        Lit::Str {
                            v: "Oslo".to_string(),
                        },
                    ),
                ]),
            ],
            None,
        )?;
        engine.schema_add_mysql_compat_index(
            &table,
            "city_idx".to_string(),
            vec!["city".to_string()],
            false,
        )?;
        drop(engine);

        let reopened = Engine::open(&dir)?;
        let (schema, tdata) = reopened.get_table(&table)?;
        let secondary_index_count = tdata
            .secondary_indexes
            .lock()
            .map(|guard| guard.len())
            .unwrap_or_default();
        assert_eq!(secondary_index_count, 1);
        let mut filters = HashMap::new();
        filters.insert(
            "city".to_string(),
            Lit::Str {
                v: "Oslo".to_string(),
            },
        );
        let candidates = secondary_index_candidates(schema, tdata, &filters).unwrap_or_default();
        assert_eq!(candidates.len(), 2);

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

