    #[test]
    fn edge_bundle_status_detects_coverage_gap() -> anyhow::Result<()> {
        let dir = temp_dir("edge_bundle_gap");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "users",
            vec![ColumnSchema {
                name: "id".to_string(),
                r#type: type_desc("u64"),
                nullable: false,
                auto_increment: false,
            }],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let table = BaseTableRef {
            db: "app".to_string(),
            table: "users".to_string(),
            r#as: None,
        };
        for id in 1..=3u64 {
            engine.data_insert(&table, vec![row(&[("id", Lit::U64 { v: id })])], None)?;
        }

        let query = Query {
            with: Vec::new(),
            body: Box::new(QueryBody::Select {
                select: Box::new(SelectBody {
                    distinct: None,
                    projection: vec![SelectItem {
                        expr: Expr::Col {
                            col: "id".to_string(),
                            table: None,
                        },
                        r#as: None,
                    }],
                    from: Some(vec![TableRef::Base(table.clone())]),
                    r#where: None,
                    group_by: None,
                    having: None,
                }),
            }),
            order_by: Vec::new(),
            limit: None,
            lock: None,
        };

        let first = engine.edge_bundle_request(EdgeBundleRequestParams {
            windows: vec![EdgeBundleWindow {
                table: table.clone(),
                from_seq: Some(0),
                to_seq: Some(1),
                max_events: None,
            }],
            redaction: None,
            bundle_id: Some("gap_1".to_string()),
        })?;
        let second = engine.edge_bundle_request(EdgeBundleRequestParams {
            windows: vec![EdgeBundleWindow {
                table: table.clone(),
                from_seq: Some(2),
                to_seq: Some(3),
                max_events: None,
            }],
            redaction: None,
            bundle_id: Some("gap_2".to_string()),
        })?;

        engine.edge_bundle_apply(EdgeBundleApplyParams {
            bundle: first.bundle,
        })?;
        engine.edge_bundle_apply(EdgeBundleApplyParams {
            bundle: second.bundle,
        })?;

        let status = engine.edge_bundle_status(EdgeBundleStatusParams {
            query: Some(query),
            max_lag: Some(0),
        })?;
        assert_eq!(status.coverage.len(), 2);
        let route = status.route.expect("missing edge route");
        assert!(!route.eligible);
        assert_eq!(route.reason.as_deref(), Some("coverage_gap"));
        assert_eq!(route.observed_lag, 2);

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn schema_evolution_add_column_and_conflict() -> anyhow::Result<()> {
        let dir = temp_dir("schema_evolution");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "users",
            vec![ColumnSchema {
                name: "id".to_string(),
                r#type: type_desc("u64"),
                nullable: false,
                auto_increment: false,
            }],
            vec!["id".to_string()],
            false,
            None,
        )?;

        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            vec![row(&[("id", Lit::U64 { v: 1 })])],
            None,
        )?;

        let change = SchemaProposeChangeParams {
            table: BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            base_version: 1,
            changes: vec![SchemaChangeOp::AddColumn {
                name: "region".to_string(),
                r#type: type_desc("str"),
                nullable: true,
                auto_increment: false,
                default: Some(Lit::Str {
                    v: "eu".to_string(),
                }),
            }],
            message: None,
        };
        let res = engine.schema_propose_change(change)?;
        assert_eq!(res.status, "pending");

        let conflict = SchemaProposeChangeParams {
            table: BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            base_version: 1,
            changes: vec![SchemaChangeOp::AddColumn {
                name: "region".to_string(),
                r#type: type_desc("u64"),
                nullable: true,
                auto_increment: false,
                default: None,
            }],
            message: None,
        };
        let conflict_res = engine.schema_propose_change(conflict)?;

        let status = engine.schema_merge_status(SchemaMergeStatusParams {
            table: BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
        })?;
        assert!(status.merge_plan.contains(&res.change_id));
        assert!(status
            .conflicts
            .iter()
            .any(|c| c.change_id == conflict_res.change_id));

        let applied = engine.schema_apply_merge(SchemaApplyMergeParams {
            table: BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            change_ids: Some(vec![res.change_id.clone()]),
        })?;
        assert_eq!(applied.applied, vec![res.change_id]);
        assert_eq!(applied.new_version, 2);

        let schema = engine.get_schema("app", "users")?;
        assert!(schema.columns.iter().any(|c| c.name == "region"));

        let row = engine
            .data_get(
                &BaseTableRef {
                    db: "app".to_string(),
                    table: "users".to_string(),
                    r#as: None,
                },
                vec![Lit::U64 { v: 1 }],
            )?
            .row;
        assert_eq!(
            row.get("region"),
            Some(&Lit::Str {
                v: "eu".to_string()
            })
        );

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn schema_evolution_merges_concurrent_column_and_index_changes() -> anyhow::Result<()> {
        let dir = temp_dir("schema_evolution_index_merge");
        let mut engine = Engine::open(&dir)?;
        let table = BaseTableRef {
            db: "app".to_string(),
            table: "users".to_string(),
            r#as: None,
        };
        engine.create_table(
            &table.db,
            &table.table,
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "email".to_string(),
                    r#type: type_desc("str"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        engine.data_insert(
            &table,
            vec![row(&[
                ("id", Lit::U64 { v: 1 }),
                (
                    "email",
                    Lit::Str {
                        v: "ada@example.com".to_string(),
                    },
                ),
            ])],
            None,
        )?;

        let add_column = engine.schema_propose_change(SchemaProposeChangeParams {
            table: table.clone(),
            base_version: 1,
            changes: vec![SchemaChangeOp::AddColumn {
                name: "region".to_string(),
                r#type: type_desc("str"),
                nullable: true,
                auto_increment: false,
                default: Some(Lit::Str {
                    v: "eu".to_string(),
                }),
            }],
            message: Some("add rollout region".to_string()),
        })?;
        let add_index = engine.schema_propose_change(SchemaProposeChangeParams {
            table: table.clone(),
            base_version: 1,
            changes: vec![SchemaChangeOp::AddIndex {
                name: "region_lookup".to_string(),
                columns: vec!["region".to_string()],
                unique: false,
            }],
            message: Some("index the rollout column".to_string()),
        })?;
        let conflict = engine.schema_propose_change(SchemaProposeChangeParams {
            table: table.clone(),
            base_version: 1,
            changes: vec![SchemaChangeOp::AddIndex {
                name: "region_lookup".to_string(),
                columns: vec!["id".to_string()],
                unique: false,
            }],
            message: Some("conflicting index name".to_string()),
        })?;

        let status = engine.schema_merge_status(SchemaMergeStatusParams {
            table: table.clone(),
        })?;
        assert_eq!(
            status.merge_plan,
            vec![add_column.change_id.clone(), add_index.change_id.clone()]
        );
        let resolution = status
            .resolution
            .iter()
            .map(|entry| {
                (
                    entry.change_id.clone(),
                    (entry.action.clone(), entry.reason.clone()),
                )
            })
            .collect::<HashMap<_, _>>();
        assert_eq!(
            resolution.get(&add_column.change_id),
            Some(&(
                "roll_forward".to_string(),
                "eligible_merge_plan".to_string()
            ))
        );
        assert_eq!(
            resolution.get(&add_index.change_id),
            Some(&(
                "roll_forward".to_string(),
                "eligible_merge_plan".to_string()
            ))
        );
        assert_eq!(
            resolution.get(&conflict.change_id),
            Some(&(
                "rollback".to_string(),
                format!("index_conflict:{}", add_index.change_id)
            ))
        );
        let conflict_reason = status
            .conflicts
            .iter()
            .find(|entry| entry.change_id == conflict.change_id)
            .map(|entry| entry.reason.clone())
            .unwrap_or_default();
        assert!(conflict_reason.starts_with("index_conflict:"));

        let applied = engine.schema_apply_merge(SchemaApplyMergeParams {
            table: table.clone(),
            change_ids: None,
        })?;
        assert_eq!(applied.applied, status.merge_plan);
        assert_eq!(applied.rolled_back.len(), 1);
        assert_eq!(applied.rolled_back[0].change_id, conflict.change_id);
        assert!(applied.rolled_back[0].reason.starts_with("index_conflict:"));
        assert_eq!(applied.new_version, 3);

        let post_status = engine.schema_merge_status(SchemaMergeStatusParams {
            table: table.clone(),
        })?;
        assert!(post_status.pending.is_empty());
        assert!(post_status.conflicts.is_empty());
        assert!(post_status.merge_plan.is_empty());

        let conflict_entry = engine
            .schema_changes
            .iter()
            .find(|entry| entry.id == conflict.change_id)
            .expect("missing rejected schema change");
        assert_eq!(conflict_entry.status, "rejected");

        let schema = engine.get_schema(&table.db, &table.table)?;
        assert!(schema.columns.iter().any(|column| column.name == "region"));
        assert!(mysql_compat_index_defs(schema).iter().any(|index| {
            index.name == "region_lookup" && index.columns == vec!["region".to_string()]
        }));

        let row = engine.data_get(&table, vec![Lit::U64 { v: 1 }])?.row;
        assert_eq!(
            row.get("region"),
            Some(&Lit::Str {
                v: "eu".to_string(),
            })
        );

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn schema_merge_status_proposes_resolution_actions() -> anyhow::Result<()> {
        let dir = temp_dir("schema_merge_status_resolution_actions");
        let mut engine = Engine::open(&dir)?;
        let table = BaseTableRef {
            db: "app".to_string(),
            table: "users".to_string(),
            r#as: None,
        };

        engine.create_table(
            &table.db,
            &table.table,
            vec![ColumnSchema {
                name: "id".to_string(),
                r#type: type_desc("u64"),
                nullable: false,
                auto_increment: false,
            }],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let winner = engine.schema_propose_change(SchemaProposeChangeParams {
            table: table.clone(),
            base_version: 1,
            changes: vec![SchemaChangeOp::AddColumn {
                name: "region".to_string(),
                r#type: type_desc("str"),
                nullable: true,
                auto_increment: false,
                default: Some(Lit::Str {
                    v: "eu".to_string(),
                }),
            }],
            message: Some("winner".to_string()),
        })?;
        let loser = engine.schema_propose_change(SchemaProposeChangeParams {
            table: table.clone(),
            base_version: 1,
            changes: vec![SchemaChangeOp::AddColumn {
                name: "region".to_string(),
                r#type: type_desc("u64"),
                nullable: true,
                auto_increment: false,
                default: None,
            }],
            message: Some("loser".to_string()),
        })?;
        engine.schema_changes.push(SchemaChangeEntry {
            id: "sch_future".to_string(),
            table: table.clone(),
            base_version: 3,
            changes: vec![SchemaChangeOp::AddColumn {
                name: "timezone".to_string(),
                r#type: type_desc("str"),
                nullable: true,
                auto_increment: false,
                default: Some(Lit::Str {
                    v: "UTC".to_string(),
                }),
            }],
            message: Some("future-base".to_string()),
            created_at_ms: now_millis().saturating_add(1),
            status: "pending".to_string(),
            applied_at_ms: None,
        });

        let status = engine.schema_merge_status(SchemaMergeStatusParams {
            table: table.clone(),
        })?;
        let resolution = status
            .resolution
            .iter()
            .map(|entry| {
                (
                    entry.change_id.clone(),
                    (entry.action.clone(), entry.reason.clone()),
                )
            })
            .collect::<HashMap<_, _>>();

        assert_eq!(
            resolution.get(&winner.change_id),
            Some(&(
                "roll_forward".to_string(),
                "eligible_merge_plan".to_string()
            ))
        );
        assert_eq!(
            resolution.get(&loser.change_id),
            Some(&(
                "rollback".to_string(),
                format!("column_conflict:{}", winner.change_id)
            ))
        );
        assert_eq!(
            resolution.get("sch_future"),
            Some(&("wait".to_string(), "future_base_version".to_string()))
        );

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn schema_simulate_rollout_reports_mixed_version_waves() -> anyhow::Result<()> {
        let dir = temp_dir("schema_simulate_rollout_waves");
        let mut engine = Engine::open(&dir)?;
        let table = BaseTableRef {
            db: "app".to_string(),
            table: "users".to_string(),
            r#as: None,
        };

        engine.create_table(
            &table.db,
            &table.table,
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "email".to_string(),
                    r#type: type_desc("str"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        engine.data_insert(
            &table,
            vec![row(&[
                ("id", Lit::U64 { v: 1 }),
                (
                    "email",
                    Lit::Str {
                        v: "ada@example.com".to_string(),
                    },
                ),
            ])],
            None,
        )?;

        let add_column = engine.schema_propose_change(SchemaProposeChangeParams {
            table: table.clone(),
            base_version: 1,
            changes: vec![SchemaChangeOp::AddColumn {
                name: "region".to_string(),
                r#type: type_desc("str"),
                nullable: true,
                auto_increment: false,
                default: Some(Lit::Str {
                    v: "eu".to_string(),
                }),
            }],
            message: Some("add region".to_string()),
        })?;
        let add_index = engine.schema_propose_change(SchemaProposeChangeParams {
            table: table.clone(),
            base_version: 1,
            changes: vec![SchemaChangeOp::AddIndex {
                name: "region_lookup".to_string(),
                columns: vec!["region".to_string()],
                unique: false,
            }],
            message: Some("index region".to_string()),
        })?;
        let conflict = engine.schema_propose_change(SchemaProposeChangeParams {
            table: table.clone(),
            base_version: 1,
            changes: vec![SchemaChangeOp::AddIndex {
                name: "region_lookup".to_string(),
                columns: vec!["email".to_string()],
                unique: false,
            }],
            message: Some("conflicting name".to_string()),
        })?;

        let rollout = engine.schema_simulate_rollout(SchemaSimulateRolloutParams {
            table: table.clone(),
            nodes: Some(3),
        })?;

        assert_eq!(rollout.format, SCHEMA_SIMULATE_ROLLOUT_FORMAT_V1);
        assert_eq!(rollout.current_version, 1);
        assert_eq!(rollout.target_version, 3);
        assert_eq!(rollout.nodes, 3);
        assert_eq!(rollout.pending_change_count, 3);
        assert!(rollout.ready_for_rollout);
        assert_eq!(rollout.legacy_row_count, 1);
        assert!(rollout.requires_query_adaptation);
        assert_eq!(
            rollout.merge_plan,
            vec![add_column.change_id.clone(), add_index.change_id.clone()]
        );
        assert_eq!(rollout.conflicts.len(), 1);
        assert_eq!(rollout.conflicts[0].change_id, conflict.change_id);
        assert_eq!(rollout.stages.len(), 4);
        assert_eq!(rollout.stages[0].stage, "prepare");
        assert_eq!(rollout.stages[1].stage, "mixed");
        assert!(rollout.stages[1].mixed_versions);
        assert!(rollout.stages[1].requires_query_adaptation);
        let final_stage = rollout.stages.last().expect("missing final rollout stage");
        assert_eq!(final_stage.stage, "steady_state");
        assert_eq!(final_stage.upgraded_nodes, 3);
        assert_eq!(final_stage.legacy_nodes, 0);
        assert!(final_stage.requires_row_adaptation);
        assert!(rollout
            .resolution
            .iter()
            .any(|entry| entry.change_id == conflict.change_id && entry.action == "rollback"));

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

