    #[test]
    fn vector_prefilter_candidates_match_bucket() -> anyhow::Result<()> {
        let dir = temp_dir("vector_prefilter");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "docs",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "embedding".to_string(),
                    r#type: type_desc("embedding"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let rows = vec![
            row(&[
                ("id", Lit::U64 { v: 1 }),
                (
                    "embedding",
                    Lit::Embedding {
                        dims: 3,
                        v: vec![1.0, 0.0, 0.0],
                        model: None,
                    },
                ),
            ]),
            row(&[
                ("id", Lit::U64 { v: 2 }),
                (
                    "embedding",
                    Lit::Embedding {
                        dims: 3,
                        v: vec![0.8, 0.0, 0.0],
                        model: None,
                    },
                ),
            ]),
            row(&[
                ("id", Lit::U64 { v: 3 }),
                (
                    "embedding",
                    Lit::Embedding {
                        dims: 3,
                        v: vec![-1.0, 0.0, 0.0],
                        model: None,
                    },
                ),
            ]),
        ];
        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "docs".to_string(),
                r#as: None,
            },
            rows,
            None,
        )?;

        let (schema, tdata) = engine.get_table(&BaseTableRef {
            db: "app".to_string(),
            table: "docs".to_string(),
            r#as: None,
        })?;
        let query_vec = vec![1.0, 0.0, 0.0];
        let candidates =
            vector_prefilter_candidates(schema, tdata, "embedding", &query_vec).unwrap();
        let bucket = embedding_lsh_bucket(&query_vec);
        let mut expected = Vec::new();
        for (idx, entry) in tdata.rows.iter().enumerate() {
            if entry.deleted {
                continue;
            }
            let Some(lit) = entry.row.get("embedding") else {
                continue;
            };
            let (_, vec, _) = embedding_ref(lit)?;
            if embedding_lsh_bucket(vec) == bucket {
                expected.push(idx);
            }
        }
        assert_eq!(candidates, expected);

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn embedding_value_id_combines_lsh_bucket_and_content_hash() -> anyhow::Result<()> {
        let lit = Lit::Embedding {
            dims: 3,
            v: vec![0.25, -0.5, 0.75],
            model: Some("text-embed-v1".to_string()),
        };
        let item = value_store_item(&lit).expect("embedding value-store item");
        assert_eq!(item.kind, ValueKind::Embedding);

        let bytes = embedding_bytes(3, &[0.25, -0.5, 0.75], Some("text-embed-v1"))
            .expect("embedding bytes");
        let bucket = embedding_lsh_bucket(&[0.25, -0.5, 0.75]);
        let hash = value_id(&bytes);

        assert_eq!(item.bytes, bytes);
        assert_eq!(u64::from_le_bytes(item.id[0..8].try_into()?), bucket);
        assert_eq!(&item.id[8..16], &hash[0..8]);
        assert_eq!(item.id, embedding_value_id(bucket, &item.bytes));
        Ok(())
    }

