    #[test]
    fn vector_search_cache_metadata_tracks_source_table_changes() -> anyhow::Result<()> {
        let dir = temp_dir("vector_search_cache_deps");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "docs",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "title".to_string(),
                    r#type: type_desc("string"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "embedding".to_string(),
                    r#type: type_desc("embedding"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let table = BaseTableRef {
            db: "app".to_string(),
            table: "docs".to_string(),
            r#as: None,
        };
        engine.data_insert(
            &table,
            vec![
                row(&[
                    ("id", Lit::U64 { v: 1 }),
                    (
                        "title",
                        Lit::Str {
                            v: "alpha".to_string(),
                        },
                    ),
                    (
                        "embedding",
                        Lit::Embedding {
                            dims: 3,
                            v: vec![1.0, 0.0, 0.0],
                            model: None,
                        },
                    ),
                ]),
                row(&[
                    ("id", Lit::U64 { v: 2 }),
                    (
                        "title",
                        Lit::Str {
                            v: "beta".to_string(),
                        },
                    ),
                    (
                        "embedding",
                        Lit::Embedding {
                            dims: 3,
                            v: vec![0.0, 1.0, 0.0],
                            model: None,
                        },
                    ),
                ]),
            ],
            None,
        )?;
        engine.vector_insert(VectorInsertParams {
            table: table.clone(),
            column: "embedding".to_string(),
            rows: vec![
                skeindb_skeinql::methods::VectorInsertRow {
                    pk: vec![Lit::U64 { v: 1 }],
                    embedding: Lit::Embedding {
                        dims: 3,
                        v: vec![1.0, 0.0, 0.0],
                        model: None,
                    },
                },
                skeindb_skeinql::methods::VectorInsertRow {
                    pk: vec![Lit::U64 { v: 2 }],
                    embedding: Lit::Embedding {
                        dims: 3,
                        v: vec![0.0, 1.0, 0.0],
                        model: None,
                    },
                },
            ],
            upsert: true,
        })?;
        assert_eq!(engine.hnsw_indexes.read().unwrap().len(), 1);

        let query_embedding = Lit::Embedding {
            dims: 3,
            v: vec![1.0, 0.0, 0.0],
            model: None,
        };
        let search_params = |cache| VectorSearchParams {
            table: table.clone(),
            column: "embedding".to_string(),
            query: query_embedding.clone(),
            k: Some(1),
            metric: Some("cosine".to_string()),
            filter: None,
            include_row: Some(true),
            use_lsh: Some(false),
            cache,
        };

        let first =
            engine.vector_search(search_params(Some(skeindb_skeinql::types::QueryCache {
                want_etag: Some(true),
                if_none_match: None,
                min_causality: None,
                mode: None,
                persist: None,
            })))?;
        assert!(!first.not_modified);
        assert_eq!(first.matches.len(), 1);
        let first_etag = first.etag.clone().expect("vector.search etag");
        let first_deps = first.deps.as_ref().expect("vector.search deps");
        assert_eq!(first_deps["vector"]["table"], "app.docs");
        assert_eq!(first_deps["vector"]["column"], "embedding");
        assert_eq!(first_deps["vector"]["source"], "table_version");
        assert_eq!(first_deps["tables"][0]["table"], "app.docs");
        let first_table_version = first_deps["tables"][0]["v"]
            .as_u64()
            .expect("source table version");

        let cached =
            engine.vector_search(search_params(Some(skeindb_skeinql::types::QueryCache {
                want_etag: Some(true),
                if_none_match: Some(first_etag.clone()),
                min_causality: first.causality.clone(),
                mode: None,
                persist: None,
            })))?;
        assert!(cached.not_modified);
        assert!(cached.matches.is_empty());
        assert_eq!(cached.etag.as_deref(), Some(first_etag.as_str()));

        let mut updates = RowObject::new();
        updates.insert(
            "title".to_string(),
            Lit::Str {
                v: "alpha refreshed".to_string(),
            },
        );
        engine.data_update(
            &table,
            &eq_expr(
                Expr::Col {
                    col: "id".to_string(),
                    table: None,
                },
                Expr::Lit {
                    lit: Lit::U64 { v: 1 },
                },
            ),
            &updates,
            None,
            None,
            &[],
        )?;
        assert!(engine.hnsw_indexes.read().unwrap().is_empty());

        let changed =
            engine.vector_search(search_params(Some(skeindb_skeinql::types::QueryCache {
                want_etag: Some(true),
                if_none_match: Some(first_etag.clone()),
                min_causality: None,
                mode: None,
                persist: None,
            })))?;
        assert!(!changed.not_modified);
        assert_ne!(changed.etag.as_deref(), Some(first_etag.as_str()));
        let changed_deps = changed.deps.as_ref().expect("changed deps");
        assert!(
            changed_deps["tables"][0]["v"]
                .as_u64()
                .expect("changed source table version")
                > first_table_version
        );
        assert_eq!(
            changed.matches[0]
                .row
                .as_ref()
                .and_then(|row| row.get("title")),
            Some(&Lit::Str {
                v: "alpha refreshed".to_string()
            })
        );

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn sql_autoparam_extract_normalizes() -> anyhow::Result<()> {
        let extract =
            sql_autoparam_extract("SELECT * FROM users WHERE status = 'active' AND id = 42");
        assert_eq!(
            extract.normalized_sql,
            "select * from users where status = ? and id = ?"
        );
        assert_eq!(extract.literals.len(), 2);
        assert_eq!(extract.literals[0].column.as_deref(), Some("status"));
        assert_eq!(extract.literals[0].table.as_deref(), Some("users"));
        assert_eq!(extract.literals[1].column.as_deref(), Some("id"));
        assert_eq!(extract.literals[1].table.as_deref(), Some("users"));
        Ok(())
    }

