    #[test]
    fn snapshot_incremental_refresh() -> anyhow::Result<()> {
        let dir = temp_dir("snap_refresh");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "users",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "city".to_string(),
                    r#type: type_desc("string"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let rows = vec![
            row(&[
                ("id", Lit::U64 { v: 1 }),
                (
                    "city",
                    Lit::Str {
                        v: "Madrid".to_string(),
                    },
                ),
            ]),
            row(&[
                ("id", Lit::U64 { v: 2 }),
                (
                    "city",
                    Lit::Str {
                        v: "Rome".to_string(),
                    },
                ),
            ]),
        ];
        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            rows,
            None,
        )?;

        engine.build_column_snapshot(
            "app",
            "users",
            Some(vec!["id".to_string(), "city".to_string()]),
            now_micros(),
        )?;

        let predicate = eq_expr(
            Expr::Col {
                col: "id".to_string(),
                table: None,
            },
            Expr::Lit {
                lit: Lit::U64 { v: 1 },
            },
        );
        let mut set = RowObject::new();
        set.insert(
            "city".to_string(),
            Lit::Str {
                v: "Berlin".to_string(),
            },
        );
        engine.data_update(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            &predicate,
            &set,
            None,
            None,
            &[],
        )?;

        let query = base_query(
            "app",
            "users",
            vec![Expr::Col {
                col: "city".to_string(),
                table: None,
            }],
            Some(eq_expr(
                Expr::Col {
                    col: "id".to_string(),
                    table: None,
                },
                Expr::Lit {
                    lit: Lit::U64 { v: 1 },
                },
            )),
        );
        let (_cols, rows) = execute_select(&engine, &query, &[], None)?;
        assert_eq!(
            rows[0],
            vec![Lit::Str {
                v: "Berlin".to_string()
            }]
        );

        let delete_pred = eq_expr(
            Expr::Col {
                col: "id".to_string(),
                table: None,
            },
            Expr::Lit {
                lit: Lit::U64 { v: 2 },
            },
        );
        engine.data_delete(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            &delete_pred,
            None,
            &[],
        )?;

        let key = TableKey {
            db: "app".to_string(),
            table: "users".to_string(),
        };
        let snapshot_rows = engine
            .snapshots
            .lock()
            .unwrap()
            .snapshots
            .get(&key)
            .unwrap()[0]
            .rows
            .len();
        assert_eq!(snapshot_rows, 1);

        let list: Vec<ColumnSnapshotDisk> =
            load_json(&dir.join("snapshots.json")).unwrap_or_default();
        assert_eq!(list.len(), 1);
        let snapshot_dir = dir.join("snapshots").join(snapshot_dir_name(&list[0].id));
        let manifest: ColumnSnapshotManifestDisk =
            load_json(&snapshot_dir.join("manifest.json")).expect("missing snapshot manifest");
        let city_segment = manifest
            .segments
            .iter()
            .find(|segment| segment.column == "city" && !segment.is_pk)
            .expect("missing city segment");
        let city = read_snapshot_cseg(&snapshot_dir.join(&city_segment.file))?;
        assert_eq!(
            city.values,
            vec![Lit::Str {
                v: "Berlin".to_string(),
            }]
        );

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn snapshot_cseg_roundtrip_preserves_typed_literals() -> anyhow::Result<()> {
        let dir = temp_dir("snap_cseg_roundtrip");
        fs::create_dir_all(&dir)?;

        let values = vec![
            Lit::Null,
            Lit::Bool { v: true },
            Lit::I64 { v: -7 },
            Lit::U64 { v: 42 },
            Lit::F64 { v: 1.5 },
            Lit::Dec {
                v: "12.34".to_string(),
            },
            Lit::Str {
                v: "hello".to_string(),
            },
            Lit::Bytes {
                b64: "AAEC".to_string(),
            },
            Lit::Json {
                v: serde_json::json!({"ok": true, "n": 3}),
            },
            Lit::Embedding {
                dims: 2,
                v: vec![1.0, 2.5],
                model: Some("test-model".to_string()),
            },
            Lit::Date {
                iso: "2026-04-19".to_string(),
            },
            Lit::Time {
                iso: "12:34:56Z".to_string(),
            },
            Lit::Datetime {
                iso: "2026-04-19T12:34:56Z".to_string(),
            },
            Lit::Uuid {
                v: "123e4567-e89b-12d3-a456-426614174000".to_string(),
            },
        ];

        let snapshot = ColumnSnapshotDisk {
            format_version: SNAPSHOT_FORMAT_VERSION,
            id: "test-snapshot".to_string(),
            db: "app".to_string(),
            table: "mixed".to_string(),
            columns: vec!["value".to_string()],
            pk_columns: vec!["id".to_string()],
            snapshot_ts: 123_456_789,
            table_version: 1,
            rows: Vec::new(),
        };

        let path = dir.join("col-0001.cseg");
        let meta = write_snapshot_cseg(&path, &snapshot, "value", false, "col-0001.cseg", &values)?;
        assert_eq!(meta.row_count, values.len() as u64);
        assert_eq!(meta.non_null_count, values.len() as u64 - 1);

        let decoded = read_snapshot_cseg(&path)?;
        assert_eq!(decoded.db, "app");
        assert_eq!(decoded.table, "mixed");
        assert_eq!(decoded.column, "value");
        assert!(!decoded.is_pk);
        assert_eq!(decoded.snapshot_ts, 123_456_789);
        assert_eq!(decoded.values, values);

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

