    #[test]
    fn dp_budget_consumption_and_exhaustion() -> anyhow::Result<()> {
        let dir = temp_dir("dp_budget");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "events",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "value".to_string(),
                    r#type: type_desc("f64"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let rows = vec![
            row(&[("id", Lit::U64 { v: 1 }), ("value", Lit::F64 { v: 3.0 })]),
            row(&[("id", Lit::U64 { v: 2 }), ("value", Lit::F64 { v: 7.0 })]),
        ];
        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "events".to_string(),
                r#as: None,
            },
            rows,
            None,
        )?;

        engine.dp_budget_set(DpBudgetSetParams {
            principal: "analyst".to_string(),
            total_epsilon: 1.0,
            total_delta: 1e-6,
            refresh_window_ms: None,
        })?;

        let result = engine.dp_aggregate(DpAggregateParams {
            table: BaseTableRef {
                db: "app".to_string(),
                table: "events".to_string(),
                r#as: None,
            },
            aggregates: vec![
                DpAggregateSpec {
                    op: "count".to_string(),
                    column: None,
                    percentile: None,
                    bounds: None,
                    r#as: None,
                },
                DpAggregateSpec {
                    op: "sum".to_string(),
                    column: Some("value".to_string()),
                    percentile: None,
                    bounds: Some(DpBounds {
                        min: 0.0,
                        max: 10.0,
                    }),
                    r#as: None,
                },
                DpAggregateSpec {
                    op: "avg".to_string(),
                    column: Some("value".to_string()),
                    percentile: None,
                    bounds: Some(DpBounds {
                        min: 0.0,
                        max: 10.0,
                    }),
                    r#as: None,
                },
            ],
            r#where: None,
            group_by: Vec::new(),
            epsilon: 0.6,
            delta: Some(1e-6),
            mechanism: Some("laplace".to_string()),
            principal: Some("analyst".to_string()),
            seed: Some(11),
        })?;

        assert_eq!(result.columns, vec!["count", "sum_value", "avg_value"]);
        let privacy = result.privacy.as_ref().expect("dp privacy metadata");
        assert!(privacy["privacy_etag"]
            .as_str()
            .unwrap_or_default()
            .starts_with("W/\"dp:"));
        assert!(privacy["table_version"].as_u64().unwrap_or_default() > 0);
        let aggregates = privacy["aggregates"]
            .as_array()
            .expect("aggregate privacy specs");
        assert_eq!(aggregates.len(), 3);
        assert_eq!(aggregates[0]["op"].as_str(), Some("count"));
        assert_eq!(aggregates[1]["op"].as_str(), Some("sum"));
        assert_eq!(aggregates[2]["op"].as_str(), Some("avg"));
        assert_eq!(aggregates[0]["sensitivity"].as_f64(), Some(1.0));
        assert_eq!(aggregates[1]["sensitivity"].as_f64(), Some(10.0));
        assert_eq!(aggregates[2]["sensitivity"].as_f64(), Some(10.0));

        let budgets = engine.dp_budget_get(DpBudgetGetParams {
            principal: Some("analyst".to_string()),
            include_usage: Some(false),
        })?;
        let consumed = budgets.budgets[0]["consumed_epsilon"]
            .as_f64()
            .unwrap_or_default();
        assert!((consumed - 0.6).abs() < 1e-6);

        let audit = engine.dp_audit_log(DpAuditLogParams {
            principal: Some("analyst".to_string()),
            from_id: None,
            limit: Some(10),
        })?;
        assert_eq!(audit.events.len(), 1);
        assert_eq!(audit.events[0]["principal"].as_str(), Some("analyst"));
        assert_eq!(audit.events[0]["mechanism"].as_str(), Some("laplace"));
        assert_eq!(audit.events[0]["aggregates"].as_array().unwrap().len(), 3);

        drop(engine);
        let mut engine = Engine::open(&dir)?;
        let persisted = engine.dp_budget_get(DpBudgetGetParams {
            principal: Some("analyst".to_string()),
            include_usage: Some(true),
        })?;
        assert_eq!(persisted.budgets.len(), 1);
        let persisted_consumed = persisted.budgets[0]["consumed_epsilon"]
            .as_f64()
            .unwrap_or_default();
        assert!((persisted_consumed - 0.6).abs() < 1e-6);
        assert_eq!(persisted.usage.unwrap().len(), 1);
        let persisted_audit = engine.dp_audit_log(DpAuditLogParams {
            principal: Some("analyst".to_string()),
            from_id: Some(1),
            limit: Some(10),
        })?;
        assert_eq!(persisted_audit.events.len(), 1);

        let err = engine
            .dp_aggregate(DpAggregateParams {
                table: BaseTableRef {
                    db: "app".to_string(),
                    table: "events".to_string(),
                    r#as: None,
                },
                aggregates: vec![DpAggregateSpec {
                    op: "count".to_string(),
                    column: None,
                    percentile: None,
                    bounds: None,
                    r#as: None,
                }],
                r#where: None,
                group_by: Vec::new(),
                epsilon: 0.6,
                delta: Some(1e-6),
                mechanism: Some("laplace".to_string()),
                principal: Some("analyst".to_string()),
                seed: Some(22),
            })
            .unwrap_err();
        assert_eq!(err.to_string(), "dp_budget_exhausted");

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn dp_aggregate_deterministic_noise() -> anyhow::Result<()> {
        let dir = temp_dir("dp_noise");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "metrics",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "score".to_string(),
                    r#type: type_desc("f64"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let rows = vec![
            row(&[("id", Lit::U64 { v: 1 }), ("score", Lit::F64 { v: 4.0 })]),
            row(&[("id", Lit::U64 { v: 2 }), ("score", Lit::F64 { v: 6.0 })]),
        ];
        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "metrics".to_string(),
                r#as: None,
            },
            rows,
            None,
        )?;

        let res = engine.dp_aggregate(DpAggregateParams {
            table: BaseTableRef {
                db: "app".to_string(),
                table: "metrics".to_string(),
                r#as: None,
            },
            aggregates: vec![
                DpAggregateSpec {
                    op: "count".to_string(),
                    column: None,
                    percentile: None,
                    bounds: None,
                    r#as: None,
                },
                DpAggregateSpec {
                    op: "sum".to_string(),
                    column: Some("score".to_string()),
                    percentile: None,
                    bounds: Some(DpBounds {
                        min: 0.0,
                        max: 10.0,
                    }),
                    r#as: None,
                },
            ],
            r#where: None,
            group_by: Vec::new(),
            epsilon: 1.0,
            delta: None,
            mechanism: Some("laplace".to_string()),
            principal: None,
            seed: Some(123),
        })?;

        let mut rng = DpRng::new(123);
        let count_noise = dp_laplace_noise(&mut rng, 1.0 / 0.5);
        let sum_noise = dp_laplace_noise(&mut rng, 10.0 / 0.5);
        let expected_count = 2.0 + count_noise;
        let expected_sum = 10.0 + sum_noise;

        let row = &res.rows[0];
        let count_lit: Lit = serde_json::from_value(row[0].clone())?;
        let sum_lit: Lit = serde_json::from_value(row[1].clone())?;
        match count_lit {
            Lit::F64 { v } => assert!((v - expected_count).abs() < 1e-6),
            _ => panic!("expected count as f64"),
        }
        match sum_lit {
            Lit::F64 { v } => assert!((v - expected_sum).abs() < 1e-6),
            _ => panic!("expected sum as f64"),
        }

        let gaussian = DpAggregateParams {
            table: BaseTableRef {
                db: "app".to_string(),
                table: "metrics".to_string(),
                r#as: None,
            },
            aggregates: vec![DpAggregateSpec {
                op: "avg".to_string(),
                column: Some("score".to_string()),
                percentile: None,
                bounds: Some(DpBounds {
                    min: 0.0,
                    max: 10.0,
                }),
                r#as: None,
            }],
            r#where: None,
            group_by: Vec::new(),
            epsilon: 1.0,
            delta: Some(1e-6),
            mechanism: Some("gaussian".to_string()),
            principal: None,
            seed: Some(456),
        };
        let gaussian_one = engine.dp_aggregate(gaussian.clone())?;
        let gaussian_two = engine.dp_aggregate(gaussian)?;
        assert_eq!(gaussian_one.rows, gaussian_two.rows);
        assert_eq!(
            gaussian_one
                .privacy
                .as_ref()
                .and_then(|privacy| privacy["mechanism"].as_str()),
            Some("gaussian")
        );

        let err = engine
            .dp_aggregate(DpAggregateParams {
                table: BaseTableRef {
                    db: "app".to_string(),
                    table: "metrics".to_string(),
                    r#as: None,
                },
                aggregates: vec![DpAggregateSpec {
                    op: "count".to_string(),
                    column: None,
                    percentile: None,
                    bounds: None,
                    r#as: None,
                }],
                r#where: None,
                group_by: Vec::new(),
                epsilon: 1.0,
                delta: None,
                mechanism: Some("gaussian".to_string()),
                principal: None,
                seed: Some(456),
            })
            .unwrap_err();
        assert_eq!(err.to_string(), "invalid_request: gaussian requires delta");

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

