    #[test]
    fn forensic_chain_verify_and_detect_tamper() -> anyhow::Result<()> {
        let dir = temp_dir("forensic_chain");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "audit",
            vec![ColumnSchema {
                name: "id".to_string(),
                r#type: type_desc("u64"),
                nullable: false,
                auto_increment: false,
            }],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let rows = vec![
            row(&[("id", Lit::U64 { v: 1 })]),
            row(&[("id", Lit::U64 { v: 2 })]),
        ];
        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "audit".to_string(),
                r#as: None,
            },
            rows,
            None,
        )?;

        let result = engine.forensic_query(ForensicQueryParams {
            table: None,
            op: None,
            filter: None,
            from_id: None,
            to_id: None,
            limit: None,
        })?;
        let verify = engine.forensic_verify(ForensicVerifyParams {
            records: result.records.clone(),
            start_hash: result.proof["preceding_hash"]
                .as_str()
                .map(|s| s.to_string()),
        })?;
        assert!(verify.ok);
        assert_eq!(
            result.proof["format"].as_str(),
            Some("skein.forensic.proof.v1")
        );
        assert_eq!(
            result.proof["inclusion_proofs"]
                .as_array()
                .map(|items| items.len()),
            Some(result.records.len())
        );
        assert_eq!(
            result.proof["index_summary"]["by_table"]["app.audit"].as_u64(),
            Some(2)
        );
        assert_eq!(
            result.proof["index_summary"]["by_actor"]["unknown"].as_u64(),
            Some(2)
        );

        let filtered = engine.forensic_query(ForensicQueryParams {
            table: None,
            op: None,
            filter: Some(serde_json::json!({
                "op": "and",
                "args": [
                    {"op":"eq","a":{"col":"db"},"b":{"lit":{"t":"str","v":"app"}}},
                    {"op":"eq","a":{"col":"table"},"b":{"lit":{"t":"str","v":"audit"}}},
                    {"op":"ge","a":{"col":"id"},"b":{"lit":{"t":"u64","v":1}}}
                ]
            })),
            from_id: None,
            to_id: None,
            limit: None,
        })?;
        assert_eq!(filtered.records.len(), 2);

        engine.checkpoint_for_shutdown()?;
        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "audit".to_string(),
                r#as: None,
            },
            vec![row(&[("id", Lit::U64 { v: 3 })])],
            None,
        )?;
        let anchored = engine.forensic_query(ForensicQueryParams {
            table: None,
            op: Some("insert".to_string()),
            filter: Some(serde_json::json!({"table":"audit"})),
            from_id: Some(3),
            to_id: None,
            limit: Some(1),
        })?;
        assert_eq!(anchored.records.len(), 1);
        assert_eq!(anchored.proof["anchor_count"].as_u64(), Some(1));
        assert_eq!(
            anchored.proof["checkpoint_anchor"]["chain_len"].as_u64(),
            Some(2)
        );

        let mut tampered = result.records;
        if let Some(first) = tampered.first_mut() {
            if let Some(op) = first.get_mut("op") {
                *op = serde_json::Value::String("tampered".to_string());
            }
        }
        let verify = engine.forensic_verify(ForensicVerifyParams {
            records: tampered,
            start_hash: None,
        })?;
        assert!(!verify.ok);

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

