    fn merge_sum_wasm_b64() -> String {
        let bytes = wat::parse_str(
            r#"(module
                (memory (export "memory") 1 1)
                (func (export "skein_alloc") (param i32) (result i32)
                    (i32.const 0)
                )
                (func (export "skein_scalar") (param $ptr i32) (param $len i32) (result i64)
                    (local $current i64)
                    (local $incoming i64)
                    (local.set $current (i64.load (i32.add (local.get $ptr) (i32.const 2))))
                    (local.set $incoming (i64.load (i32.add (local.get $ptr) (i32.const 11))))
                    (i32.store8 (i32.const 256) (i32.const 4))
                    (i64.store (i32.const 257) (i64.add (local.get $current) (local.get $incoming)))
                    (i64.or
                        (i64.shl (i64.extend_i32_u (i32.const 256)) (i64.const 32))
                        (i64.extend_i32_u (i32.const 9))
                    )
                )
            )"#,
        )
        .unwrap();
        BASE64_STANDARD.encode(bytes)
    }

    fn merge_spin_wasm_b64() -> String {
        let bytes = wat::parse_str(
            r#"(module
                (memory (export "memory") 1 1)
                (func (export "skein_alloc") (param i32) (result i32)
                    (i32.const 0)
                )
                (func (export "skein_scalar") (param i32 i32) (result i64)
                    (loop $spin
                        (br $spin)
                    )
                    (i64.const 0)
                )
            )"#,
        )
        .unwrap();
        BASE64_STANDARD.encode(bytes)
    }

    #[test]
    fn merge_apply_resolves_conflict() -> anyhow::Result<()> {
        let dir = temp_dir("merge_apply");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "counters",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "count".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "counters".to_string(),
                r#as: None,
            },
            vec![row(&[
                ("id", Lit::U64 { v: 1 }),
                ("count", Lit::U64 { v: 5 }),
            ])],
            None,
        )?;

        let current = engine.data_get(
            &BaseTableRef {
                db: "app".to_string(),
                table: "counters".to_string(),
                r#as: None,
            },
            vec![Lit::U64 { v: 1 }],
        )?;

        let mut set = RowObject::new();
        set.insert("count".to_string(), Lit::U64 { v: 10 });
        let predicate = eq_expr(
            Expr::Col {
                col: "id".to_string(),
                table: None,
            },
            Expr::Lit {
                lit: Lit::U64 { v: 1 },
            },
        );
        engine.data_update(
            &BaseTableRef {
                db: "app".to_string(),
                table: "counters".to_string(),
                r#as: None,
            },
            &predicate,
            &set,
            None,
            None,
            &[],
        )?;

        engine.merge_register(MergeRegisterParams {
            table: BaseTableRef {
                db: "app".to_string(),
                table: "counters".to_string(),
                r#as: None,
            },
            policy: MergePolicySpec {
                default: MergeFunctionRef {
                    kind: "builtin".to_string(),
                    name: "last_write_wins".to_string(),
                    module: None,
                },
                per_column: vec![(
                    "count".to_string(),
                    MergeFunctionRef {
                        kind: "builtin".to_string(),
                        name: "sum".to_string(),
                        module: None,
                    },
                )]
                .into_iter()
                .collect(),
            },
        })?;

        let result = engine.merge_apply(MergeApplyParams {
            table: BaseTableRef {
                db: "app".to_string(),
                table: "counters".to_string(),
                r#as: None,
            },
            pk: vec![Lit::U64 { v: 1 }],
            incoming: row(&[("count", Lit::U64 { v: 3 })]),
            expected_etag: Some(current.etag),
            min_causality: None,
            policy: None,
        })?;

        assert!(result.applied);
        assert!(result.conflict);
        assert_eq!(
            result.merged.get("count").and_then(|lit| match lit {
                Lit::U64 { v } => Some(*v),
                _ => None,
            }),
            Some(13)
        );

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn merge_apply_respects_min_causality() -> anyhow::Result<()> {
        let dir = temp_dir("merge_apply_causality");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "counters",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "count".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "counters".to_string(),
                r#as: None,
            },
            vec![row(&[
                ("id", Lit::U64 { v: 1 }),
                ("count", Lit::U64 { v: 5 }),
            ])],
            None,
        )?;

        let schema = engine.get_schema("app", "counters")?;
        let stale = CausalityToken {
            format: CAUSALITY_FORMAT_V1.to_string(),
            deps: vec![CausalityDependency {
                table: "app.counters".to_string(),
                v: Some(schema.table_version + 1),
                view: None,
                change_seq: None,
                stale: None,
            }],
        };

        let result = engine.merge_apply(MergeApplyParams {
            table: BaseTableRef {
                db: "app".to_string(),
                table: "counters".to_string(),
                r#as: None,
            },
            pk: vec![Lit::U64 { v: 1 }],
            incoming: row(&[("count", Lit::U64 { v: 2 })]),
            expected_etag: None,
            min_causality: Some(stale),
            policy: None,
        })?;

        assert!(!result.applied);
        assert!(result.conflict);
        assert!(result.conflicts.iter().any(|c| c == "dependency"));

        let current = engine.data_get(
            &BaseTableRef {
                db: "app".to_string(),
                table: "counters".to_string(),
                r#as: None,
            },
            vec![Lit::U64 { v: 1 }],
        )?;
        assert_eq!(
            current.row.get("count").and_then(|lit| match lit {
                Lit::U64 { v } => Some(*v),
                _ => None,
            }),
            Some(5)
        );

        let schema = engine.get_schema("app", "counters")?;
        let ok = CausalityToken {
            format: CAUSALITY_FORMAT_V1.to_string(),
            deps: vec![CausalityDependency {
                table: "app.counters".to_string(),
                v: Some(schema.table_version),
                view: None,
                change_seq: None,
                stale: None,
            }],
        };

        let result = engine.merge_apply(MergeApplyParams {
            table: BaseTableRef {
                db: "app".to_string(),
                table: "counters".to_string(),
                r#as: None,
            },
            pk: vec![Lit::U64 { v: 1 }],
            incoming: row(&[("count", Lit::U64 { v: 2 })]),
            expected_etag: None,
            min_causality: Some(ok),
            policy: None,
        })?;

        assert!(result.applied);
        assert!(!result.conflicts.iter().any(|c| c == "dependency"));

        let updated = engine.data_get(
            &BaseTableRef {
                db: "app".to_string(),
                table: "counters".to_string(),
                r#as: None,
            },
            vec![Lit::U64 { v: 1 }],
        )?;
        assert_eq!(
            updated.row.get("count").and_then(|lit| match lit {
                Lit::U64 { v } => Some(*v),
                _ => None,
            }),
            Some(2)
        );

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

