    #[test]
    fn mysql_compat_unique_index_enforcement_tracks_updates() -> anyhow::Result<()> {
        let dir = temp_dir("mysql_unique_runtime_index");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "users",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "email".to_string(),
                    r#type: type_desc("str"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            Some(serde_json::json!({
                "indexes": [{
                    "name": "email_unique",
                    "columns": ["email"],
                    "unique": true
                }]
            })),
        )?;

        let table = BaseTableRef {
            db: "app".to_string(),
            table: "users".to_string(),
            r#as: None,
        };

        engine.data_insert(
            &table,
            vec![
                row(&[
                    ("id", Lit::U64 { v: 1 }),
                    (
                        "email",
                        Lit::Str {
                            v: "a@example.com".to_string(),
                        },
                    ),
                ]),
                row(&[
                    ("id", Lit::U64 { v: 2 }),
                    (
                        "email",
                        Lit::Str {
                            v: "b@example.com".to_string(),
                        },
                    ),
                ]),
            ],
            None,
        )?;

        let mut set = RowObject::new();
        set.insert(
            "email".to_string(),
            Lit::Str {
                v: "a@example.com".to_string(),
            },
        );
        let mut predicate = eq_expr(
            Expr::Col {
                col: "id".to_string(),
                table: None,
            },
            Expr::Lit {
                lit: Lit::U64 { v: 2 },
            },
        );
        let err = engine
            .data_update(&table, &predicate, &set, None, None, &[])
            .expect_err("expected unique conflict");
        assert!(err.to_string().contains("duplicate key"));

        set.insert(
            "email".to_string(),
            Lit::Str {
                v: "c@example.com".to_string(),
            },
        );
        let moved = engine.data_update(&table, &predicate, &set, None, None, &[])?;
        assert_eq!(moved.affected, 1);

        set.insert(
            "email".to_string(),
            Lit::Str {
                v: "b@example.com".to_string(),
            },
        );
        predicate = eq_expr(
            Expr::Col {
                col: "id".to_string(),
                table: None,
            },
            Expr::Lit {
                lit: Lit::U64 { v: 1 },
            },
        );
        let reused = engine.data_update(&table, &predicate, &set, None, None, &[])?;
        assert_eq!(reused.affected, 1);

        let err = engine
            .data_insert(
                &table,
                vec![row(&[
                    ("id", Lit::U64 { v: 3 }),
                    (
                        "email",
                        Lit::Str {
                            v: "b@example.com".to_string(),
                        },
                    ),
                ])],
                None,
            )
            .expect_err("expected duplicate insert conflict");
        assert!(err.to_string().contains("duplicate key"));

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn primary_key_updates_reject_duplicates_and_refresh_pk_lookup() -> anyhow::Result<()> {
        let dir = temp_dir("mysql_primary_key_update_conflict");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "users",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "email".to_string(),
                    r#type: type_desc("str"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let table = BaseTableRef {
            db: "app".to_string(),
            table: "users".to_string(),
            r#as: None,
        };
        engine.data_insert(
            &table,
            vec![
                row(&[
                    ("id", Lit::U64 { v: 1 }),
                    (
                        "email",
                        Lit::Str {
                            v: "a@example.com".to_string(),
                        },
                    ),
                ]),
                row(&[
                    ("id", Lit::U64 { v: 2 }),
                    (
                        "email",
                        Lit::Str {
                            v: "b@example.com".to_string(),
                        },
                    ),
                ]),
            ],
            None,
        )?;

        let mut set = RowObject::new();
        set.insert("id".to_string(), Lit::U64 { v: 1 });
        let predicate = eq_expr(
            Expr::Col {
                col: "id".to_string(),
                table: None,
            },
            Expr::Lit {
                lit: Lit::U64 { v: 2 },
            },
        );
        let err = engine
            .data_update(&table, &predicate, &set, None, None, &[])
            .expect_err("expected primary-key duplicate conflict");
        assert!(err.to_string().contains("duplicate key"));

        set.insert("id".to_string(), Lit::U64 { v: 3 });
        let moved = engine.data_update(&table, &predicate, &set, None, None, &[])?;
        assert_eq!(moved.affected, 1);
        assert!(engine.data_get(&table, vec![Lit::U64 { v: 2 }]).is_err());
        let moved_row = engine.data_get(&table, vec![Lit::U64 { v: 3 }])?;
        assert_eq!(
            moved_row.row.get("email"),
            Some(&Lit::Str {
                v: "b@example.com".to_string()
            })
        );

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn secondary_index_cache_persists_and_reloads() -> anyhow::Result<()> {
        let dir = temp_dir("secondary_index_cache_persist");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "users",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "email".to_string(),
                    r#type: type_desc("str"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            Some(serde_json::json!({
                "indexes": [{
                    "name": "email_unique",
                    "columns": ["email"],
                    "unique": true
                }]
            })),
        )?;

        let table = BaseTableRef {
            db: "app".to_string(),
            table: "users".to_string(),
            r#as: None,
        };
        engine.data_insert(
            &table,
            vec![
                row(&[
                    ("id", Lit::U64 { v: 1 }),
                    (
                        "email",
                        Lit::Str {
                            v: "a@example.com".to_string(),
                        },
                    ),
                ]),
                row(&[
                    ("id", Lit::U64 { v: 2 }),
                    (
                        "email",
                        Lit::Str {
                            v: "b@example.com".to_string(),
                        },
                    ),
                ]),
            ],
            None,
        )?;

        engine.flush_dirty_tables()?;
        let index_cache_path = engine.table_secondary_index_path("app", "users");
        let disk = load_json::<SecondaryIndexCacheDisk>(&index_cache_path)
            .expect("secondary index cache should be persisted");
        assert_eq!(disk.format_version, SECONDARY_INDEX_CACHE_FORMAT_VERSION);
        assert_eq!(disk.row_count, 2);
        assert_eq!(disk.indexes.len(), 1);

        drop(engine);

        let mut reopened = Engine::open(&dir)?;
        let (_schema, tdata) = reopened.get_table(&table)?;
        let index_count = tdata
            .secondary_indexes
            .lock()
            .map(|guard| guard.len())
            .unwrap_or_default();
        assert_eq!(index_count, 1);
        let err = reopened
            .data_insert(
                &table,
                vec![row(&[
                    ("id", Lit::U64 { v: 3 }),
                    (
                        "email",
                        Lit::Str {
                            v: "a@example.com".to_string(),
                        },
                    ),
                ])],
                None,
            )
            .expect_err("expected duplicate-key conflict after reopen");
        assert!(err.to_string().contains("duplicate key"));

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

