    #[test]
    fn mysql_compat_modify_and_change_column_updates_schema_rows_and_indexes() -> anyhow::Result<()>
    {
        let dir = temp_dir("mysql_modify_change_column");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "posts",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "slug".to_string(),
                    r#type: type_desc("str"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            Some(serde_json::json!({
                "column_defaults": {
                    "slug": {"t": "str", "v": ""}
                },
                "indexes": [{
                    "name": "slug_unique",
                    "columns": ["slug"],
                    "unique": true
                }]
            })),
        )?;

        let table = BaseTableRef {
            db: "app".to_string(),
            table: "posts".to_string(),
            r#as: None,
        };
        engine.data_insert(
            &table,
            vec![
                row(&[
                    ("id", Lit::U64 { v: 1 }),
                    (
                        "slug",
                        Lit::Str {
                            v: "hello".to_string(),
                        },
                    ),
                ]),
                row(&[
                    ("id", Lit::U64 { v: 2 }),
                    (
                        "slug",
                        Lit::Str {
                            v: "world".to_string(),
                        },
                    ),
                ]),
            ],
            None,
        )?;

        engine.schema_modify_mysql_compat_column(
            &table,
            "slug",
            ColumnSchema {
                name: "slug".to_string(),
                r#type: type_desc("str"),
                nullable: false,
                auto_increment: false,
            },
            Some(Lit::Str {
                v: "n-a".to_string(),
            }),
        )?;

        engine.data_insert(&table, vec![row(&[("id", Lit::U64 { v: 3 })])], None)?;
        let row_three = engine.data_get(&table, vec![Lit::U64 { v: 3 }])?;
        assert_eq!(
            row_three.row.get("slug"),
            Some(&Lit::Str {
                v: "n-a".to_string()
            })
        );

        engine.schema_modify_mysql_compat_column(
            &table,
            "slug",
            ColumnSchema {
                name: "post_slug".to_string(),
                r#type: type_desc("str"),
                nullable: false,
                auto_increment: false,
            },
            Some(Lit::Str {
                v: "n-a".to_string(),
            }),
        )?;

        let renamed = engine.data_get(&table, vec![Lit::U64 { v: 3 }])?;
        assert_eq!(
            renamed.row.get("post_slug"),
            Some(&Lit::Str {
                v: "n-a".to_string()
            })
        );
        assert!(!renamed.row.contains_key("slug"));

        let err = engine
            .data_insert(
                &table,
                vec![row(&[
                    ("id", Lit::U64 { v: 4 }),
                    (
                        "post_slug",
                        Lit::Str {
                            v: "hello".to_string(),
                        },
                    ),
                ])],
                None,
            )
            .expect_err("expected renamed unique index conflict");
        assert!(err.to_string().contains("duplicate key"));

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn mysql_compat_rename_column_updates_schema_rows_and_indexes() -> anyhow::Result<()> {
        let dir = temp_dir("mysql_compat_rename_column");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "posts",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "slug".to_string(),
                    r#type: type_desc("str"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            Some(serde_json::json!({
                "column_defaults": {
                    "slug": {"t": "str", "v": "n-a"}
                },
                "indexes": [{
                    "name": "slug_unique",
                    "columns": ["slug"],
                    "unique": true
                }]
            })),
        )?;

        let table = BaseTableRef {
            db: "app".to_string(),
            table: "posts".to_string(),
            r#as: None,
        };
        engine.data_insert(
            &table,
            vec![row(&[
                ("id", Lit::U64 { v: 1 }),
                (
                    "slug",
                    Lit::Str {
                        v: "hello".to_string(),
                    },
                ),
            ])],
            None,
        )?;

        engine.schema_rename_mysql_compat_column(&table, "slug", "post_slug")?;

        let desc = engine.describe_table("app", "posts")?;
        assert!(desc
            .get("compat_mysql")
            .and_then(|v| v.get("column_defaults"))
            .and_then(|v| v.get("slug"))
            .is_none());
        assert_eq!(
            desc.get("compat_mysql")
                .and_then(|v| v.get("column_defaults"))
                .and_then(|v| v.get("post_slug"))
                .and_then(|v| serde_json::from_value::<Lit>(v.clone()).ok()),
            Some(Lit::Str {
                v: "n-a".to_string()
            })
        );
        assert_eq!(
            desc.get("indexes")
                .and_then(|v| v.as_array())
                .and_then(|indexes| indexes.first())
                .and_then(|index| index.get("columns"))
                .and_then(|v| v.as_array())
                .and_then(|cols| cols.first())
                .and_then(|v| v.as_str()),
            Some("post_slug")
        );

        let fetched = engine.data_get(&table, vec![Lit::U64 { v: 1 }])?;
        assert_eq!(
            fetched.row.get("post_slug"),
            Some(&Lit::Str {
                v: "hello".to_string()
            })
        );
        assert!(!fetched.row.contains_key("slug"));

        let err = engine
            .data_insert(
                &table,
                vec![row(&[
                    ("id", Lit::U64 { v: 2 }),
                    (
                        "post_slug",
                        Lit::Str {
                            v: "hello".to_string(),
                        },
                    ),
                ])],
                None,
            )
            .expect_err("expected renamed unique index conflict");
        assert!(err.to_string().contains("duplicate key"));

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

