    #[test]
    fn view_grouped_incremental_refresh_updates_groups() -> anyhow::Result<()> {
        let dir = temp_dir("view_grouped_refresh");
        let mut engine = Engine::open(&dir)?;

        engine.create_table(
            "app",
            "users",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "city".to_string(),
                    r#type: type_desc("string"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "score".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;
        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            vec![
                row(&[
                    ("id", Lit::U64 { v: 1 }),
                    (
                        "city",
                        Lit::Str {
                            v: "Oslo".to_string(),
                        },
                    ),
                    ("score", Lit::U64 { v: 5 }),
                ]),
                row(&[
                    ("id", Lit::U64 { v: 2 }),
                    (
                        "city",
                        Lit::Str {
                            v: "Oslo".to_string(),
                        },
                    ),
                    ("score", Lit::U64 { v: 7 }),
                ]),
                row(&[
                    ("id", Lit::U64 { v: 3 }),
                    (
                        "city",
                        Lit::Str {
                            v: "Tokyo".to_string(),
                        },
                    ),
                    ("score", Lit::U64 { v: 10 }),
                ]),
            ],
            None,
        )?;

        let grouped_query = Query {
            with: Vec::new(),
            body: Box::new(QueryBody::Select {
                select: Box::new(SelectBody {
                    distinct: None,
                    projection: vec![
                        SelectItem {
                            expr: Expr::Col {
                                col: "city".to_string(),
                                table: None,
                            },
                            r#as: Some("city".to_string()),
                        },
                        SelectItem {
                            expr: Expr::Func {
                                name: "count".to_string(),
                                args: Vec::new(),
                                distinct: None,
                            },
                            r#as: Some("cnt".to_string()),
                        },
                        SelectItem {
                            expr: Expr::Func {
                                name: "sum".to_string(),
                                args: vec![Expr::Col {
                                    col: "score".to_string(),
                                    table: None,
                                }],
                                distinct: None,
                            },
                            r#as: Some("total".to_string()),
                        },
                    ],
                    from: Some(vec![TableRef::Base(BaseTableRef {
                        db: "app".to_string(),
                        table: "users".to_string(),
                        r#as: None,
                    })]),
                    r#where: None,
                    group_by: Some(vec![Expr::Col {
                        col: "city".to_string(),
                        table: None,
                    }]),
                    having: None,
                }),
            }),
            order_by: Vec::new(),
            limit: None,
            lock: None,
        };

        engine.view_create(ViewCreateParams {
            view: BaseTableRef {
                db: "app".to_string(),
                table: "city_scores".to_string(),
                r#as: None,
            },
            query: grouped_query,
            if_not_exists: None,
        })?;

        let status = engine.view_status(ViewStatusParams {
            view: Some(BaseTableRef {
                db: "app".to_string(),
                table: "city_scores".to_string(),
                r#as: None,
            }),
        })?;
        assert_eq!(
            status.views[0]["deps"][0]["group_by_columns"]
                .as_array()
                .cloned()
                .unwrap_or_default(),
            vec![serde_json::json!("city")]
        );

        let view_key = TableKey {
            db: "app".to_string(),
            table: "city_scores".to_string(),
        };
        let grouped_rows = |engine: &Engine| -> BTreeMap<String, (u64, f64)> {
            let view = engine.views.get(&view_key).expect("view exists");
            let mut out = BTreeMap::new();
            for row in view.rows.iter() {
                let city = match &row.values[0] {
                    Lit::Str { v } => v.clone(),
                    other => panic!("expected city string, got {other:?}"),
                };
                let count = match &row.values[1] {
                    Lit::U64 { v } => *v,
                    other => panic!("expected count u64, got {other:?}"),
                };
                let total = match &row.values[2] {
                    Lit::F64 { v } => *v,
                    Lit::U64 { v } => *v as f64,
                    Lit::I64 { v } => *v as f64,
                    other => panic!("expected numeric total, got {other:?}"),
                };
                out.insert(city, (count, total));
            }
            out
        };

        let initial = grouped_rows(&engine);
        assert_eq!(initial.len(), 2);
        assert_eq!(initial.get("Oslo"), Some(&(2, 12.0)));
        assert_eq!(initial.get("Tokyo"), Some(&(1, 10.0)));
        assert_eq!(
            engine
                .views
                .get(&view_key)
                .map(|view| view.pk_columns.clone()),
            Some(vec!["city".to_string()])
        );
        assert_eq!(
            engine
                .views
                .get(&view_key)
                .map(|view| view.source_rows.len()),
            Some(3)
        );

        let mut set = RowObject::new();
        set.insert(
            "city".to_string(),
            Lit::Str {
                v: "Oslo".to_string(),
            },
        );
        set.insert("score".to_string(), Lit::U64 { v: 11 });
        let predicate = Expr::Op {
            op: "eq".to_string(),
            a: Some(Box::new(Expr::Col {
                col: "id".to_string(),
                table: None,
            })),
            b: Some(Box::new(Expr::Lit {
                lit: Lit::U64 { v: 3 },
            })),
            args: None,
            list: None,
            lo: None,
            hi: None,
        };
        engine.data_update(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            &predicate,
            &set,
            None,
            None,
            &[],
        )?;

        let refresh = engine.view_refresh(ViewRefreshParams {
            view: BaseTableRef {
                db: "app".to_string(),
                table: "city_scores".to_string(),
                r#as: None,
            },
            mode: Some("incremental".to_string()),
        })?;
        assert_eq!(refresh.mode, "incremental");

        let after_move = grouped_rows(&engine);
        assert_eq!(after_move.len(), 1);
        assert_eq!(after_move.get("Oslo"), Some(&(3, 23.0)));

        let delete_predicate = Expr::Op {
            op: "eq".to_string(),
            a: Some(Box::new(Expr::Col {
                col: "id".to_string(),
                table: None,
            })),
            b: Some(Box::new(Expr::Lit {
                lit: Lit::U64 { v: 2 },
            })),
            args: None,
            list: None,
            lo: None,
            hi: None,
        };
        engine.data_delete(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            &delete_predicate,
            None,
            &[],
        )?;
        engine.view_refresh(ViewRefreshParams {
            view: BaseTableRef {
                db: "app".to_string(),
                table: "city_scores".to_string(),
                r#as: None,
            },
            mode: Some("incremental".to_string()),
        })?;

        let after_delete = grouped_rows(&engine);
        assert_eq!(after_delete.len(), 1);
        assert_eq!(after_delete.get("Oslo"), Some(&(2, 16.0)));

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn r08_view_correctness_oracle_random_workload_matches_full_recompute() -> anyhow::Result<()> {
        let dir = temp_dir("view_oracle_random");
        let mut engine = Engine::open(&dir)?;

        engine.create_table(
            "app",
            "users",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "city".to_string(),
                    r#type: type_desc("string"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "score".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let mut rows = Vec::new();
        for id in 1..=16_u64 {
            rows.push(row(&[
                ("id", Lit::U64 { v: id }),
                (
                    "city",
                    Lit::Str {
                        v: if id % 2 == 0 { "Oslo" } else { "Tokyo" }.to_string(),
                    },
                ),
                ("score", Lit::U64 { v: id * 3 }),
            ]));
        }
        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            rows,
            None,
        )?;

        engine.view_create(ViewCreateParams {
            view: BaseTableRef {
                db: "app".to_string(),
                table: "top_users".to_string(),
                r#as: None,
            },
            query: base_query(
                "app",
                "users",
                vec![
                    Expr::Col {
                        col: "id".to_string(),
                        table: None,
                    },
                    Expr::Col {
                        col: "city".to_string(),
                        table: None,
                    },
                ],
                Some(Expr::Op {
                    op: "gt".to_string(),
                    a: Some(Box::new(Expr::Col {
                        col: "score".to_string(),
                        table: None,
                    })),
                    b: Some(Box::new(Expr::Lit {
                        lit: Lit::U64 { v: 20 },
                    })),
                    args: None,
                    list: None,
                    lo: None,
                    hi: None,
                }),
            ),
            if_not_exists: None,
        })?;

        let mut seed = 0x5eed_u64;
        for _ in 0..24 {
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1);
            let id = (seed % 16) + 1;
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1);
            let score = seed % 60;
            let mut set = RowObject::new();
            set.insert("score".to_string(), Lit::U64 { v: score });
            engine.data_update(
                &BaseTableRef {
                    db: "app".to_string(),
                    table: "users".to_string(),
                    r#as: None,
                },
                &eq_expr(
                    Expr::Col {
                        col: "id".to_string(),
                        table: None,
                    },
                    Expr::Lit {
                        lit: Lit::U64 { v: id },
                    },
                ),
                &set,
                None,
                None,
                &[],
            )?;
        }

        let report = engine.view_evaluate(ViewEvaluateParams {
            view: BaseTableRef {
                db: "app".to_string(),
                table: "top_users".to_string(),
                r#as: None,
            },
            iterations: Some(3),
        })?;
        assert_eq!(report.format, VIEW_EVALUATE_FORMAT_V1);
        assert!(report.incremental_ok, "{:?}", report.incremental_error);
        assert!(report.correct);
        assert!(report.pending_changes > 0);
        assert_eq!(report.rows_incremental, report.rows_full);
        assert_eq!(report.recommended_mode, "full");
        assert!(report.mean_full_ns > 0);

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

