    #[test]
    fn view_refresh_rolls_back_on_incremental_error() -> anyhow::Result<()> {
        let dir = temp_dir("view_refresh_rollback");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "users",
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "city".to_string(),
                    r#type: type_desc("string"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "score".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            vec![
                row(&[
                    ("id", Lit::U64 { v: 1 }),
                    (
                        "city",
                        Lit::Str {
                            v: "Oslo".to_string(),
                        },
                    ),
                    ("score", Lit::U64 { v: 5 }),
                ]),
                row(&[
                    ("id", Lit::U64 { v: 2 }),
                    (
                        "city",
                        Lit::Str {
                            v: "Tokyo".to_string(),
                        },
                    ),
                    ("score", Lit::U64 { v: 20 }),
                ]),
            ],
            None,
        )?;

        let query = base_query(
            "app",
            "users",
            vec![
                Expr::Col {
                    col: "id".to_string(),
                    table: None,
                },
                Expr::Col {
                    col: "city".to_string(),
                    table: None,
                },
            ],
            Some(Expr::Op {
                op: "gt".to_string(),
                a: Some(Box::new(Expr::Col {
                    col: "score".to_string(),
                    table: None,
                })),
                b: Some(Box::new(Expr::Lit {
                    lit: Lit::U64 { v: 10 },
                })),
                args: None,
                list: None,
                lo: None,
                hi: None,
            }),
        );

        engine.view_create(ViewCreateParams {
            view: BaseTableRef {
                db: "app".to_string(),
                table: "top_users".to_string(),
                r#as: None,
            },
            query,
            if_not_exists: None,
        })?;

        let mut set = RowObject::new();
        set.insert("score".to_string(), Lit::U64 { v: 15 });
        let predicate = eq_expr(
            Expr::Col {
                col: "id".to_string(),
                table: None,
            },
            Expr::Lit {
                lit: Lit::U64 { v: 1 },
            },
        );
        engine.data_update(
            &BaseTableRef {
                db: "app".to_string(),
                table: "users".to_string(),
                r#as: None,
            },
            &predicate,
            &set,
            None,
            None,
            &[],
        )?;

        let view_key = TableKey {
            db: "app".to_string(),
            table: "top_users".to_string(),
        };
        let expected_view = engine
            .views
            .get(&view_key)
            .cloned()
            .expect("view should exist before failed refresh");

        engine.change_seq += 1;
        engine.changes.push(ChangeEvent {
            seq: engine.change_seq,
            db: "app".to_string(),
            table: "users".to_string(),
            op: "unsupported".to_string(),
            pk: Some(vec![Lit::U64 { v: 1 }]),
            before: None,
            after: None,
            query_id: None,
            etag: None,
            commit_ts_ms: now_millis(),
            lsn: Some(engine.change_seq),
        });

        let err = engine
            .view_refresh(ViewRefreshParams {
                view: BaseTableRef {
                    db: "app".to_string(),
                    table: "top_users".to_string(),
                    r#as: None,
                },
                mode: Some("incremental".to_string()),
            })
            .expect_err("synthetic bad change should fail incremental refresh");
        assert!(err
            .to_string()
            .contains("invalid_request: unsupported change op"));

        let view = engine
            .views
            .get(&view_key)
            .expect("view should be restored");
        assert_eq!(
            view.rows
                .iter()
                .map(|row| (row.pk.clone(), row.values.clone()))
                .collect::<Vec<_>>(),
            expected_view
                .rows
                .iter()
                .map(|row| (row.pk.clone(), row.values.clone()))
                .collect::<Vec<_>>()
        );
        assert_eq!(view.stale, expected_view.stale);
        assert_eq!(view.last_change_seq, expected_view.last_change_seq);
        assert_eq!(view.last_refresh_mode, expected_view.last_refresh_mode);

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

