    #[test]
    fn commit_ts_ms_set_on_insert_update_delete() -> anyhow::Result<()> {
        let dir = temp_dir("commit_ts_ms");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "items",
            vec![ColumnSchema {
                name: "id".to_string(),
                r#type: type_desc("int"),
                nullable: false,
                auto_increment: false,
            }],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let before = now_millis();
        engine.data_insert(
            &BaseTableRef {
                db: "app".to_string(),
                table: "items".to_string(),
                r#as: None,
            },
            vec![row(&[("id", Lit::U64 { v: 1 })])],
            None,
        )?;
        let after = now_millis();

        // Check commit_ts_ms was set on insert.
        {
            let (_, tdata) = engine.get_table(&BaseTableRef {
                db: "app".to_string(),
                table: "items".to_string(),
                r#as: None,
            })?;
            let entry = &tdata.rows[0];
            assert!(
                entry.commit_ts_ms >= before && entry.commit_ts_ms <= after,
                "commit_ts_ms {} not in range [{}, {}]",
                entry.commit_ts_ms,
                before,
                after
            );
        }

        // Update — commit_ts_ms should advance.
        std::thread::sleep(std::time::Duration::from_millis(2));
        let before_update = now_millis();
        engine.data_update(
            &BaseTableRef {
                db: "app".to_string(),
                table: "items".to_string(),
                r#as: None,
            },
            &Expr::Lit {
                lit: Lit::Bool { v: true },
            },
            &row(&[("id", Lit::U64 { v: 1 })]),
            None,
            None,
            &[],
        )?;
        {
            let (_, tdata) = engine.get_table(&BaseTableRef {
                db: "app".to_string(),
                table: "items".to_string(),
                r#as: None,
            })?;
            assert!(tdata.rows[0].commit_ts_ms >= before_update);
        }

        // Delete — commit_ts_ms should advance.
        std::thread::sleep(std::time::Duration::from_millis(2));
        let before_delete = now_millis();
        engine.data_delete(
            &BaseTableRef {
                db: "app".to_string(),
                table: "items".to_string(),
                r#as: None,
            },
            &Expr::Lit {
                lit: Lit::Bool { v: true },
            },
            None,
            &[],
        )?;
        {
            let (_, tdata) = engine.get_table(&BaseTableRef {
                db: "app".to_string(),
                table: "items".to_string(),
                r#as: None,
            })?;
            assert!(tdata.rows[0].deleted);
            assert!(tdata.rows[0].commit_ts_ms >= before_delete);
        }

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn row_visible_at_helper() {
        let entry_live = RowEntry {
            row: RowObject::new(),
            version: 1,
            schema_version: 1,
            deleted: false,
            commit_ts_ms: 100,
        };
        let entry_deleted = RowEntry {
            row: RowObject::new(),
            version: 2,
            schema_version: 1,
            deleted: true,
            commit_ts_ms: 200,
        };
        let entry_pre_tt = RowEntry {
            row: RowObject::new(),
            version: 1,
            schema_version: 1,
            deleted: false,
            commit_ts_ms: 0,
        };

        // No as_of: live visible, deleted not.
        assert!(row_visible_at(&entry_live, None));
        assert!(!row_visible_at(&entry_deleted, None));

        // As-of at 150: live row (committed at 100) visible.
        assert!(row_visible_at(&entry_live, Some(150)));
        // As-of at 50: live row (committed at 100) NOT visible.
        assert!(!row_visible_at(&entry_live, Some(50)));

        // As-of at 150: deleted row (deleted at 200) should be visible (deletion in future).
        assert!(row_visible_at(&entry_deleted, Some(150)));
        // As-of at 250: deleted row (deleted at 200) not visible.
        assert!(!row_visible_at(&entry_deleted, Some(250)));

        // Pre-time-travel row (commit_ts_ms == 0): always visible if not deleted.
        assert!(row_visible_at(&entry_pre_tt, Some(50)));
        assert!(row_visible_at(&entry_pre_tt, Some(0)));
    }

    #[test]
    fn schema_version_tags_row_entries_and_normalizes_legacy_rows() -> anyhow::Result<()> {
        let dir = temp_dir("row_schema_version_tags");
        let table = BaseTableRef {
            db: "app".to_string(),
            table: "items".to_string(),
            r#as: None,
        };

        {
            let mut engine = Engine::open(&dir)?;
            engine.create_table(
                &table.db,
                &table.table,
                vec![ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("int"),
                    nullable: false,
                    auto_increment: false,
                }],
                vec!["id".to_string()],
                false,
                None,
            )?;

            engine.data_insert(&table, vec![row(&[("id", Lit::U64 { v: 1 })])], None)?;
            let change = engine.schema_propose_change(SchemaProposeChangeParams {
                table: table.clone(),
                base_version: 1,
                changes: vec![SchemaChangeOp::AddColumn {
                    name: "title".to_string(),
                    r#type: type_desc("str"),
                    nullable: true,
                    auto_increment: false,
                    default: None,
                }],
                message: None,
            })?;
            let applied = engine.schema_apply_merge(SchemaApplyMergeParams {
                table: table.clone(),
                change_ids: Some(vec![change.change_id]),
            })?;
            assert_eq!(applied.new_version, 2);

            {
                let (_, tdata) = engine.get_table(&table)?;
                assert_eq!(tdata.rows.len(), 1);
                assert_eq!(tdata.rows[0].schema_version, 2);
                assert!(matches!(tdata.rows[0].row.get("title"), Some(Lit::Null)));
            }

            engine.data_insert(
                &table,
                vec![row(&[
                    ("id", Lit::U64 { v: 2 }),
                    (
                        "title",
                        Lit::Str {
                            v: "second".to_string(),
                        },
                    ),
                ])],
                None,
            )?;

            {
                let (_, tdata) = engine.get_table(&table)?;
                assert_eq!(tdata.rows.len(), 2);
                assert!(tdata.rows.iter().all(|entry| entry.schema_version == 2));
            }

            let json_path = engine.table_path(&table.db, &table.table);
            let segment_path = engine.table_segment_path(&table.db, &table.table);
            let legacy_rows = serde_json::json!({
                "format_version": 2,
                "rows": [
                    {
                        "row": serde_json::to_value(row(&[
                            ("id", Lit::U64 { v: 1 }),
                            ("title", Lit::Null),
                        ]))?,
                        "version": 1,
                        "deleted": false,
                        "commit_ts_ms": 11
                    },
                    {
                        "row": serde_json::to_value(row(&[
                            ("id", Lit::U64 { v: 2 }),
                            (
                                "title",
                                Lit::Str {
                                    v: "second".to_string(),
                                },
                            ),
                        ]))?,
                        "version": 2,
                        "deleted": false,
                        "commit_ts_ms": 12
                    }
                ]
            });
            save_json(&json_path, &legacy_rows)?;
            remove_file_if_exists(&segment_path)?;
        }

        // This test fabricates a legacy on-disk table that predates the WAL, so drop any
        // WAL the setup inserts produced; otherwise recovery would (correctly) replay the
        // originally committed rows over the hand-written legacy snapshot.
        fs::remove_dir_all(dir.join("wal")).ok();

        let reopened = Engine::open(&dir)?;
        let (_, tdata) = reopened.get_table(&table)?;
        assert_eq!(tdata.rows.len(), 2);
        assert!(tdata.rows.iter().all(|entry| entry.schema_version == 2));
        assert_eq!(tdata.rows[0].commit_ts_ms, 11);
        assert_eq!(tdata.rows[1].commit_ts_ms, 12);

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    // ------------------------------------------------------------------
    // T182 — History retention policy & GC
    // ------------------------------------------------------------------

    #[test]
    fn history_gc_purges_old_tombstones_and_preserves_live_rows() -> anyhow::Result<()> {
        let dir = temp_dir("history_gc_basic");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "items",
            vec![ColumnSchema {
                name: "id".to_string(),
                r#type: type_desc("int"),
                nullable: false,
                auto_increment: false,
            }],
            vec!["id".to_string()],
            false,
            None,
        )?;
        let tref = BaseTableRef {
            db: "app".to_string(),
            table: "items".to_string(),
            r#as: None,
        };
        engine.data_insert(
            &tref,
            vec![
                row(&[("id", Lit::U64 { v: 1 })]),
                row(&[("id", Lit::U64 { v: 2 })]),
                row(&[("id", Lit::U64 { v: 3 })]),
            ],
            None,
        )?;

        // Delete id=2 — creates tombstone with commit_ts_ms == now.
        engine.data_delete(
            &tref,
            &eq_expr(
                Expr::Col {
                    col: "id".to_string(),
                    table: None,
                },
                Expr::Lit {
                    lit: Lit::U64 { v: 2 },
                },
            ),
            None,
            &[],
        )?;

        // Status before GC: 1 tombstone purgeable at far-future horizon.
        let horizon = now_millis() + 10_000;
        let status_before = engine.maintenance_history_status(Some(horizon));
        assert_eq!(status_before["total_live_rows"].as_u64().unwrap(), 2);
        assert_eq!(status_before["total_tombstones"].as_u64().unwrap(), 1);
        assert_eq!(status_before["total_purgeable"].as_u64().unwrap(), 1);

        // Run GC.
        let gc = engine.maintenance_history_gc(Some(horizon))?;
        assert_eq!(gc["rows_purged"].as_u64().unwrap(), 1);
        assert_eq!(gc["tables_touched"].as_u64().unwrap(), 1);

        // Status after GC: tombstone gone.
        let status_after = engine.maintenance_history_status(Some(horizon));
        assert_eq!(status_after["total_live_rows"].as_u64().unwrap(), 2);
        assert_eq!(status_after["total_tombstones"].as_u64().unwrap(), 0);

        // Live rows still queryable (pk_index rebuilt).
        let q = base_query(
            "app",
            "items",
            vec![Expr::Col {
                col: "id".to_string(),
                table: None,
            }],
            None,
        );
        let r = engine.query_select(
            &q,
            &[],
            ResultFormat::RowsJson,
            false,
            None,
            None,
            None,
            false,
            None,
        )?;
        let rows = r.data.unwrap()["rows"].as_array().unwrap().len();
        assert_eq!(rows, 2);

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn schema_interned_flags_persist_rename_and_drop() -> anyhow::Result<()> {
        let dir = temp_dir("schema_interned_flags");
        let mut engine = Engine::open(&dir)?;
        let table = BaseTableRef {
            db: "app".to_string(),
            table: "users".to_string(),
            r#as: None,
        };
        let key = TableKey {
            db: table.db.clone(),
            table: table.table.clone(),
        };

        engine.create_table(
            &table.db,
            &table.table,
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "name".to_string(),
                    r#type: type_desc("str"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "city".to_string(),
                    r#type: type_desc("str"),
                    nullable: true,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        engine.schema_set_column_interned(&table, "name", true)?;
        let describe = engine.describe_table(&table.db, &table.table)?;
        let columns = describe["columns"].as_array().unwrap();
        assert!(columns
            .iter()
            .find(|column| column["name"] == "name")
            .and_then(|column| column["interned"].as_bool())
            .unwrap_or(false));
        assert!(!columns
            .iter()
            .find(|column| column["name"] == "city")
            .and_then(|column| column["interned"].as_bool())
            .unwrap_or(true));

        engine.schema_rename_mysql_compat_column(&table, "name", "handle")?;
        assert!(engine.column_is_interned(&key, "handle"));
        assert!(!engine.column_is_interned(&key, "name"));

        engine.checkpoint_for_shutdown()?;
        let flags_disk: serde_json::Value =
            serde_json::from_slice(&fs::read(dir.join("schema_flags.json"))?)?;
        assert_eq!(
            flags_disk["format_version"].as_u64(),
            Some(SCHEMA_FLAGS_FORMAT_VERSION as u64)
        );
        assert_eq!(
            flags_disk["tables"][0]["interned_columns"][0].as_str(),
            Some("handle")
        );

        let mut reopened = Engine::open(&dir)?;
        let reopened_describe = reopened.describe_table(&table.db, &table.table)?;
        let reopened_columns = reopened_describe["columns"].as_array().unwrap();
        assert!(reopened_columns
            .iter()
            .find(|column| column["name"] == "handle")
            .and_then(|column| column["interned"].as_bool())
            .unwrap_or(false));

        reopened.schema_drop_mysql_compat_column(&table, "handle")?;
        assert!(!reopened.schema_flags.contains_key(&key));

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn interned_predicate_plan_requires_flag_and_supports_eq_and_in() -> anyhow::Result<()> {
        let dir = temp_dir("interned_predicate_plan");
        let mut engine = Engine::open(&dir)?;
        let table = BaseTableRef {
            db: "app".to_string(),
            table: "users".to_string(),
            r#as: None,
        };

        engine.create_table(
            &table.db,
            &table.table,
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "name".to_string(),
                    r#type: type_desc("str"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let eq_param = eq_expr(
            Expr::Col {
                col: "name".to_string(),
                table: None,
            },
            Expr::Param { param: 0 },
        );
        assert!(compile_interned_predicate_for_base(
            &engine,
            &table,
            Some(&eq_param),
            &[Lit::Str {
                v: "Alice".to_string(),
            }],
        )
        .is_none());

        engine.schema_set_column_interned(&table, "name", true)?;

        let eq_plan = compile_interned_predicate_for_base(
            &engine,
            &table,
            Some(&eq_param),
            &[Lit::Str {
                v: "Alice".to_string(),
            }],
        )
        .expect("eq predicate should compile for interned column");
        let alice = row(&[(
            "name",
            Lit::Str {
                v: "Alice".to_string(),
            },
        )]);
        let bob = row(&[(
            "name",
            Lit::Str {
                v: "Bob".to_string(),
            },
        )]);
        assert_eq!(
            compiled_interned_predicate_matches_row(&eq_plan, &alice),
            Some(true)
        );
        assert_eq!(
            compiled_interned_predicate_matches_row(&eq_plan, &bob),
            Some(false)
        );

        let in_predicate = Expr::Op {
            op: "in".to_string(),
            a: Some(Box::new(Expr::Col {
                col: "name".to_string(),
                table: None,
            })),
            b: None,
            args: None,
            list: Some(vec![
                Expr::Lit {
                    lit: Lit::Str {
                        v: "Alice".to_string(),
                    },
                },
                Expr::Lit {
                    lit: Lit::Str {
                        v: "Carol".to_string(),
                    },
                },
                Expr::Lit { lit: Lit::Null },
            ]),
            lo: None,
            hi: None,
        };
        let in_plan =
            compile_interned_predicate_for_base(&engine, &table, Some(&in_predicate), &[])
                .expect("in predicate should compile for interned column");
        assert_eq!(
            compiled_interned_predicate_matches_row(&in_plan, &alice),
            Some(true)
        );
        assert_eq!(
            compiled_interned_predicate_matches_row(&in_plan, &bob),
            Some(false)
        );

        let like_predicate = Expr::Op {
            op: "like".to_string(),
            a: Some(Box::new(Expr::Col {
                col: "name".to_string(),
                table: None,
            })),
            b: Some(Box::new(Expr::Lit {
                lit: Lit::Str {
                    v: "A%".to_string(),
                },
            })),
            args: None,
            list: None,
            lo: None,
            hi: None,
        };
        assert!(
            compile_interned_predicate_for_base(&engine, &table, Some(&like_predicate), &[])
                .is_none()
        );

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

