    #[test]
    fn row_scan_batch_respects_fixed_batch_size() {
        let schema = TableSchema {
            columns: vec![ColumnSchema {
                name: "id".to_string(),
                r#type: type_desc("u64"),
                nullable: false,
                auto_increment: false,
            }],
            primary_key: vec!["id".to_string()],
            table_version: 1,
            auto_inc_next: HashMap::new(),
            compat_mysql: None,
        };
        let rows = (0..(SELECT_BATCH_SIZE + 3))
            .map(|idx| RowEntry {
                row: row(&[("id", Lit::U64 { v: idx as u64 })]),
                version: 1,
                schema_version: 1,
                deleted: false,
                commit_ts_ms: 0,
            })
            .collect::<Vec<_>>();
        let columns = vec!["id".to_string()];

        let (batch, next_idx, rows_scanned) =
            scan_row_entries_batch(&schema, &rows, 0, &columns, None).expect("first batch");
        assert_eq!(batch.row_count, SELECT_BATCH_SIZE);
        assert_eq!(rows_scanned, SELECT_BATCH_SIZE as u64);
        assert_eq!(next_idx, SELECT_BATCH_SIZE);

        let (tail, tail_next_idx, tail_rows_scanned) =
            scan_row_entries_batch(&schema, &rows, next_idx, &columns, None).expect("tail batch");
        assert_eq!(tail.row_count, 3);
        assert_eq!(tail_rows_scanned, 3);
        assert_eq!(tail_next_idx, rows.len());
    }

    #[test]
    fn execute_select_batch_pipeline_spans_multiple_batches() -> anyhow::Result<()> {
        let dir = temp_dir("select_batch_pipeline_multi_batch");
        let mut engine = Engine::open(&dir)?;
        let table = BaseTableRef {
            db: "app".to_string(),
            table: "users".to_string(),
            r#as: None,
        };

        engine.create_table(
            &table.db,
            &table.table,
            vec![
                ColumnSchema {
                    name: "id".to_string(),
                    r#type: type_desc("u64"),
                    nullable: false,
                    auto_increment: false,
                },
                ColumnSchema {
                    name: "name".to_string(),
                    r#type: type_desc("str"),
                    nullable: false,
                    auto_increment: false,
                },
            ],
            vec!["id".to_string()],
            false,
            None,
        )?;

        let mut rows = Vec::new();
        for idx in 0..(SELECT_BATCH_SIZE + 2) {
            rows.push(row(&[
                ("id", Lit::U64 { v: idx as u64 + 1 }),
                (
                    "name",
                    Lit::Str {
                        v: if idx % 2 == 0 {
                            "Alice".to_string()
                        } else {
                            "Bob".to_string()
                        },
                    },
                ),
            ]));
        }
        engine.data_insert(&table, rows, None)?;
        engine.schema_set_column_interned(&table, "name", true)?;

        let query = base_query(
            &table.db,
            &table.table,
            vec![Expr::Col {
                col: "id".to_string(),
                table: None,
            }],
            Some(eq_expr(
                Expr::Col {
                    col: "name".to_string(),
                    table: None,
                },
                Expr::Param { param: 0 },
            )),
        );

        let (columns, rows) = execute_select(
            &engine,
            &query,
            &[Lit::Str {
                v: "Alice".to_string(),
            }],
            None,
        )?;
        assert_eq!(columns.len(), 1);
        assert_eq!(rows.len(), (SELECT_BATCH_SIZE + 2).div_ceil(2));
        assert_eq!(rows.first(), Some(&vec![Lit::U64 { v: 1 }]));
        assert_eq!(rows.last(), Some(&vec![Lit::U64 { v: 1025 }]));

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn history_gc_retains_pre_t180_tombstones() -> anyhow::Result<()> {
        let dir = temp_dir("history_gc_pre_t180");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "items",
            vec![ColumnSchema {
                name: "id".to_string(),
                r#type: type_desc("int"),
                nullable: false,
                auto_increment: false,
            }],
            vec!["id".to_string()],
            false,
            None,
        )?;
        let tref = BaseTableRef {
            db: "app".to_string(),
            table: "items".to_string(),
            r#as: None,
        };
        engine.data_insert(&tref, vec![row(&[("id", Lit::U64 { v: 1 })])], None)?;

        // Synthesise a pre-T180 tombstone: commit_ts_ms == 0, deleted == true.
        {
            let key = TableKey {
                db: "app".to_string(),
                table: "items".to_string(),
            };
            let tdata = engine.tables.get_mut(&key).expect("table");
            tdata.rows.push(RowEntry {
                row: row(&[("id", Lit::U64 { v: 99 })]),
                version: 1,
                schema_version: 1,
                deleted: true,
                commit_ts_ms: 0,
            });
        }

        // Horizon == u64::MAX should NOT purge the pre-T180 tombstone.
        let gc = engine.maintenance_history_gc(Some(u64::MAX))?;
        assert_eq!(gc["rows_purged"].as_u64().unwrap(), 0);

        let status = engine.maintenance_history_status(None);
        assert_eq!(status["total_tombstones"].as_u64().unwrap(), 1);
        assert_eq!(status["total_purgeable"].as_u64().unwrap(), 0);

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

    #[test]
    fn history_gc_horizon_filters_recent_tombstones() -> anyhow::Result<()> {
        let dir = temp_dir("history_gc_horizon");
        let mut engine = Engine::open(&dir)?;
        engine.create_table(
            "app",
            "items",
            vec![ColumnSchema {
                name: "id".to_string(),
                r#type: type_desc("int"),
                nullable: false,
                auto_increment: false,
            }],
            vec!["id".to_string()],
            false,
            None,
        )?;
        let tref = BaseTableRef {
            db: "app".to_string(),
            table: "items".to_string(),
            r#as: None,
        };
        engine.data_insert(&tref, vec![row(&[("id", Lit::U64 { v: 1 })])], None)?;

        let horizon_before = now_millis();
        std::thread::sleep(std::time::Duration::from_millis(5));

        // Delete — tombstone commit_ts_ms > horizon_before.
        engine.data_delete(
            &tref,
            &eq_expr(
                Expr::Col {
                    col: "id".to_string(),
                    table: None,
                },
                Expr::Lit {
                    lit: Lit::U64 { v: 1 },
                },
            ),
            None,
            &[],
        )?;

        // GC with the old horizon: must keep the tombstone (too recent).
        let gc = engine.maintenance_history_gc(Some(horizon_before))?;
        assert_eq!(gc["rows_purged"].as_u64().unwrap(), 0);
        let status = engine.maintenance_history_status(Some(horizon_before));
        assert_eq!(status["total_tombstones"].as_u64().unwrap(), 1);
        assert_eq!(status["total_purgeable"].as_u64().unwrap(), 0);

        fs::remove_dir_all(&dir).ok();
        Ok(())
    }

